--
-- Name: asset_owners_same_tenant_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asset_owners_same_tenant_check() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM groups g
        JOIN assets a ON a.tenant_id = g.tenant_id
        WHERE g.id = NEW.group_id AND a.id = NEW.asset_id
    ) THEN
        RAISE EXCEPTION 'asset_owners: asset % is not in the tenant of group %', NEW.asset_id, NEW.group_id
            USING ERRCODE = 'foreign_key_violation';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: asset_registry_backfill(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asset_registry_backfill(p_after uuid, p_batch integer, OUT last_id uuid, OUT updated integer) RETURNS record
    LANGUAGE plpgsql
    AS $$
BEGIN
    SELECT page.id INTO last_id FROM (
        SELECT id FROM assets
        WHERE p_after IS NULL OR id > p_after
        ORDER BY id
        LIMIT p_batch
    ) page
    ORDER BY page.id DESC
    LIMIT 1;

    IF last_id IS NULL THEN
        updated := 0;
        RETURN;
    END IF;

    UPDATE assets a
       SET asset_class = COALESCE(c.class, 'other'),
           asset_lens = c.lens
      FROM assets b
      LEFT JOIN LATERAL asset_type_classification(b.asset_type, b.sub_type) c ON TRUE
     WHERE a.id = b.id
       AND (p_after IS NULL OR b.id > p_after)
       AND b.id <= last_id
       AND (a.asset_class IS DISTINCT FROM COALESCE(c.class, 'other')
            OR a.asset_lens IS DISTINCT FROM c.lens);
    GET DIAGNOSTICS updated = ROW_COUNT;
END $$;


--
-- Name: asset_type_classification(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asset_type_classification(p_type text, p_sub_type text) RETURNS TABLE(class text, lens text)
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE(a.class, t.class)::TEXT,
           (CASE WHEN a.code IS NOT NULL THEN a.lens ELSE t.lens END)::TEXT
    FROM asset_types t
    LEFT JOIN asset_types a
           ON a.alias_of = t.code
          AND a.alias_sub_type = p_sub_type
    WHERE t.code = p_type
$$;


--
-- Name: asset_type_normalise_batch(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asset_type_normalise_batch(p_after uuid, p_batch integer, p_migration integer, OUT last_id uuid, OUT moved integer) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
    r            record;
    m            record;
    new_type     text;
    new_sub      text;
    new_provider text;
    attrs        jsonb;
    rule         text;
    left_sub     text;
    added        jsonb;
    label_old    text;
    label_new    text;
BEGIN
    moved := 0;
    SELECT page.id INTO last_id FROM (
        SELECT id FROM assets
        WHERE p_after IS NULL OR id > p_after
        ORDER BY id
        LIMIT p_batch
    ) page
    ORDER BY page.id DESC
    LIMIT 1;
    IF last_id IS NULL THEN
        RETURN;
    END IF;

    FOR r IN
        SELECT a.id, a.tenant_id, a.asset_type, NULLIF(a.sub_type, '') AS sub_type,
               a.provider, a.properties
        FROM assets a
        LEFT JOIN asset_types t ON t.code = a.asset_type
        WHERE (p_after IS NULL OR a.id > p_after) AND a.id <= last_id
          AND NOT (COALESCE(t.is_storable, false)
                   AND (NULLIF(a.sub_type, '') IS NULL OR a.sub_type = ANY (t.sub_types)))
        ORDER BY a.id
    LOOP
        new_provider := NULL;
        attrs := '{}'::jsonb;
        left_sub := r.sub_type;

        SELECT * INTO m FROM asset_type_input_map
        WHERE from_type = r.asset_type AND from_sub_type = COALESCE(r.sub_type, '');
        IF FOUND THEN
            rule := 'input';
            new_type := m.to_type;
            new_sub := m.to_sub_type;
            new_provider := m.provider;
            attrs := m.attributes;
            left_sub := NULL; -- the sub-type was the input itself
        ELSE
            SELECT * INTO m FROM asset_type_input_map
            WHERE from_type = r.asset_type AND from_sub_type = '';
            IF FOUND THEN
                rule := 'alias';
                new_type := m.to_type;
                new_sub := m.to_sub_type;
                new_provider := m.provider;
                attrs := m.attributes;
            ELSE
                SELECT * INTO m FROM asset_type_legacy_codes WHERE code = r.asset_type;
                IF FOUND THEN
                    rule := 'legacy_code';
                    new_type := m.to_type;
                    new_sub := m.to_sub_type;
                    attrs := jsonb_build_object('x_native_type', r.asset_type);
                ELSIF EXISTS (SELECT 1 FROM asset_types WHERE code = r.asset_type AND is_storable) THEN
                    rule := 'undeclared';
                    new_type := r.asset_type;
                    new_sub := NULL;
                ELSE
                    -- Not a registry type and not a known legacy code: kept
                    -- as an unclassified asset that remembers its type.
                    rule := 'legacy_code';
                    new_type := 'unclassified';
                    new_sub := NULL;
                    attrs := jsonb_build_object('x_native_type', r.asset_type);
                END IF;
            END IF;
        END IF;

        -- A sub-type the input did not account for is kept when it is a
        -- declared kind of the new type, else recorded as an attribute.
        IF left_sub IS NOT NULL AND left_sub IS DISTINCT FROM new_sub THEN
            IF new_sub IS NULL AND EXISTS (
                SELECT 1 FROM asset_types WHERE code = new_type AND left_sub = ANY (sub_types)
            ) THEN
                new_sub := left_sub;
            ELSE
                attrs := attrs || jsonb_build_object('x_native_sub_type', left_sub);
            END IF;
        END IF;

        -- A provider the asset already names wins over the one the input
        -- implied (cloud_account/aws on a gcp account); the input's value is
        -- then kept as the native sub-type instead of a contradicting
        -- properties.provider.
        IF COALESCE(NULLIF(r.provider, ''), 'other') <> 'other'
           AND attrs ? 'provider' AND attrs->>'provider' <> r.provider THEN
            attrs := (attrs - 'provider') || jsonb_build_object('x_native_sub_type', COALESCE(r.sub_type, r.asset_type));
        END IF;

        -- Never overwrite: only the properties the asset does not have.
        SELECT COALESCE(jsonb_object_agg(e.key, e.value), '{}'::jsonb) INTO added
        FROM jsonb_each(attrs) e
        WHERE NOT (r.properties ? e.key);

        IF new_provider IS NULL OR COALESCE(NULLIF(r.provider, ''), 'other') <> 'other' THEN
            new_provider := r.provider;
        END IF;

        UPDATE assets
           SET asset_type = new_type,
               sub_type = new_sub,
               provider = new_provider,
               properties = properties || added
         WHERE id = r.id;

        INSERT INTO asset_type_reclassifications
            (migration, tenant_id, asset_id, rule, old_type, old_sub_type, old_provider,
             new_type, new_sub_type, new_provider, added)
        VALUES (p_migration, r.tenant_id, r.id, rule, r.asset_type, r.sub_type, r.provider,
                new_type, new_sub, new_provider, added);

        label_old := r.asset_type || COALESCE('/' || r.sub_type, '');
        label_new := new_type || COALESCE('/' || new_sub, '');
        INSERT INTO asset_state_history
            (tenant_id, asset_id, change_type, field, old_value, new_value, reason, source, metadata)
        VALUES (r.tenant_id, r.id, 'reclassified', 'asset_type', label_old, label_new,
                'Asset type normalised to the asset type registry (RFC-042 §6.3.8)', 'system',
                jsonb_build_object('migration', p_migration, 'rule', rule));

        moved := moved + 1;
    END LOOP;
END $$;


--
-- Name: assets_sync_registry_class(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assets_sync_registry_class() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    c RECORD;
BEGIN
    SELECT * INTO c FROM asset_type_classification(NEW.asset_type, NEW.sub_type);
    IF FOUND THEN
        NEW.asset_class := c.class;
        NEW.asset_lens := c.lens;
    ELSE
        NEW.asset_class := 'other';
        NEW.asset_lens := NULL;
    END IF;
    RETURN NEW;
END $$;


--
-- Name: branch_counts_as_exposure(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.branch_counts_as_exposure(p_branch_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE((
        SELECT b.is_default OR b.is_protected OR b.branch_type IN ('main', 'release')
            OR NOT EXISTS (SELECT 1 FROM repository_branches d
                           WHERE d.repository_id = b.repository_id AND d.is_default)
        FROM repository_branches b WHERE b.id = p_branch_id
    ), TRUE)
$$;


--
-- Name: calculate_queue_priority(character varying, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_queue_priority(p_priority character varying, p_queued_at timestamp with time zone, p_tenant_id uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    base_priority INTEGER;
    wait_time_minutes INTEGER;
    tenant_active_jobs INTEGER;
    final_priority INTEGER;
BEGIN
    -- Base priority from job priority level
    base_priority := CASE p_priority
        WHEN 'critical' THEN 1000
        WHEN 'high' THEN 750
        WHEN 'normal' THEN 500
        WHEN 'low' THEN 250
        ELSE 500
    END;

    -- Add wait time bonus (1 point per minute waiting, max 200)
    wait_time_minutes := EXTRACT(EPOCH FROM (NOW() - COALESCE(p_queued_at, NOW()))) / 60;
    wait_time_minutes := LEAST(wait_time_minutes, 200);

    -- Reduce priority if tenant has many active jobs (fairness)
    SELECT COUNT(*) INTO tenant_active_jobs
    FROM commands
    WHERE tenant_id = p_tenant_id
    AND is_platform_job = TRUE
    AND status IN ('acknowledged', 'running');

    final_priority := base_priority + wait_time_minutes - (tenant_active_jobs * 10);

    RETURN GREATEST(final_priority, 1);
END;
$$;


--
-- Name: check_campaign_lead_after_member_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_campaign_lead_after_member_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    promoted_member RECORD;
BEGIN
    IF OLD.role = 'lead' THEN
        IF NOT EXISTS (
            SELECT 1 FROM pentest_campaign_members
            WHERE campaign_id = OLD.campaign_id AND role = 'lead'
        ) THEN
            -- Promote oldest tester. Capture the row so we can audit it.
            UPDATE pentest_campaign_members
            SET role = 'lead'
            WHERE id = (
                SELECT id FROM pentest_campaign_members
                WHERE campaign_id = OLD.campaign_id AND role = 'tester'
                ORDER BY created_at ASC
                LIMIT 1
            )
            RETURNING * INTO promoted_member;

            -- If a tester was promoted, write an audit row with a system actor.
            -- actor_id = NULL signals "system" — admins know this is automated.
            IF promoted_member.id IS NOT NULL THEN
                INSERT INTO audit_logs (
                    tenant_id,
                    actor_id,
                    actor_email,
                    action,
                    resource_type,
                    resource_id,
                    result,
                    severity,
                    message,
                    metadata
                ) VALUES (
                    promoted_member.tenant_id,
                    NULL,
                    'system@auto-promote',
                    'campaign.member_role_changed',
                    'pentest_campaign',
                    promoted_member.campaign_id::text,
                    'success',
                    'high',
                    format('Auto-promoted user %s to lead after last lead %s was removed (cascade)',
                        promoted_member.user_id, OLD.user_id),
                    jsonb_build_object(
                        'member_user_id', promoted_member.user_id,
                        'previous_role', 'tester',
                        'new_role', 'lead',
                        'reason', 'cascade_last_lead_replacement',
                        'removed_lead_user_id', OLD.user_id,
                        'automated', true
                    )
                );
            END IF;
        END IF;
    END IF;
    RETURN OLD;
END;
$$;


--
-- Name: comment_reaction_tenant_matches_comment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comment_reaction_tenant_matches_comment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    parent_tenant UUID;
BEGIN
    SELECT tenant_id INTO parent_tenant FROM finding_comments WHERE id = NEW.comment_id;
    IF parent_tenant IS NULL THEN
        RAISE EXCEPTION 'comment % not found', NEW.comment_id;
    END IF;
    IF NEW.tenant_id <> parent_tenant THEN
        RAISE EXCEPTION 'tenant_id mismatch: reaction tenant % != comment tenant %',
            NEW.tenant_id, parent_tenant;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fail_exhausted_commands(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_exhausted_commands(p_max_retries integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    failed_count INTEGER;
BEGIN
    WITH exhausted AS (
        UPDATE commands
        SET status = 'failed',
            error_message = 'Max dispatch attempts exceeded',
            completed_at = NOW()
        -- Cover both platform and tenant commands, and both queued ('pending')
        -- and claimed-but-stuck ('acknowledged') states. A command that has
        -- exhausted its dispatch attempts is dead regardless of who owns it.
        WHERE status IN ('pending', 'acknowledged')
        AND dispatch_attempts >= p_max_retries
        RETURNING id
    )
    SELECT COUNT(*) INTO failed_count FROM exhausted;

    RETURN failed_count;
END;
$$;


