--
-- Name: findings_fingerprint_alias_on_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.findings_fingerprint_alias_on_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO finding_fingerprints (tenant_id, fingerprint, finding_id, version)
    SELECT n.tenant_id, n.fingerprint, n.id, n.fingerprint_version
    FROM new_findings n
    WHERE n.fingerprint NOT LIKE 'dup:%'
    ON CONFLICT (tenant_id, fingerprint) DO UPDATE
        SET finding_id = EXCLUDED.finding_id, version = EXCLUDED.version
        WHERE finding_fingerprints.finding_id <> EXCLUDED.finding_id
           OR finding_fingerprints.version <> EXCLUDED.version;
    RETURN NULL;
END;
$$;


--
-- Name: findings_fingerprint_alias_on_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.findings_fingerprint_alias_on_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.fingerprint LIKE 'dup:%' THEN
        RETURN NULL;
    END IF;
    INSERT INTO finding_fingerprints (tenant_id, fingerprint, finding_id, version)
    VALUES (NEW.tenant_id, NEW.fingerprint, NEW.id, NEW.fingerprint_version)
    ON CONFLICT (tenant_id, fingerprint) DO UPDATE
        SET finding_id = EXCLUDED.finding_id, version = EXCLUDED.version
        WHERE finding_fingerprints.finding_id <> EXCLUDED.finding_id
           OR finding_fingerprints.version <> EXCLUDED.version;
    RETURN NULL;
END;
$$;


--
-- Name: findings_mark_branch_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.findings_mark_branch_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.branch_only := NEW.branch_id IS NOT NULL AND NOT branch_counts_as_exposure(NEW.branch_id);
    RETURN NEW;
END;
$$;


--
-- Name: forbid_platform_admin_membership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forbid_platform_admin_membership() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM admin_users WHERE user_id = NEW.user_id) THEN
        RAISE EXCEPTION 'platform administrators cannot be members of an organization'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: get_next_platform_job(uuid, text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_next_platform_job(p_sensor_id uuid, p_capabilities text[], p_tools text[]) RETURNS TABLE(command_id uuid, tenant_id uuid, command_type character varying, payload jsonb, queued_at timestamp with time zone, auth_token character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_command_id UUID;
    v_tenant_id UUID;
    v_command_type VARCHAR;
    v_payload JSONB;
    v_queued_at TIMESTAMPTZ;
    v_auth_token_prefix VARCHAR;
BEGIN
    SELECT c.id, c.tenant_id, c.type, c.payload, c.queued_at, c.auth_token_prefix
    INTO v_command_id, v_tenant_id, v_command_type, v_payload, v_queued_at, v_auth_token_prefix
    FROM commands c
    LEFT JOIN (
        SELECT l.tenant_id, count(*) AS in_flight
        FROM commands l
        WHERE l.is_platform_job = TRUE
          AND l.status IN ('acknowledged', 'running')
        GROUP BY l.tenant_id
    ) load ON load.tenant_id = c.tenant_id
    WHERE c.is_platform_job = TRUE
    AND c.status = 'pending'
    AND c.platform_sensor_id IS NULL
    AND (c.expires_at IS NULL OR c.expires_at > NOW())
    AND (
        COALESCE(NULLIF(c.payload->>'scanner', ''), NULLIF(c.payload->>'preferred_tool', '')) IS NULL
        OR COALESCE(NULLIF(c.payload->>'scanner', ''), NULLIF(c.payload->>'preferred_tool', ''))
           = ANY(COALESCE(p_tools, ARRAY[]::text[]))
    )
    AND (
        jsonb_typeof(c.payload->'required_capabilities') IS DISTINCT FROM 'array'
        OR NOT EXISTS (
            SELECT 1
            FROM jsonb_array_elements_text(c.payload->'required_capabilities') AS rc(cap)
            WHERE rc.cap <> ALL(COALESCE(p_capabilities, ARRAY[]::text[]))
        )
    )
    ORDER BY
        -- Priority class, one class up per 30 minutes queued, never into
        -- critical and never down on clock skew.
        CASE c.priority
            WHEN 'critical' THEN 1
            ELSE GREATEST(2,
                (CASE c.priority WHEN 'high' THEN 2 WHEN 'normal' THEN 3 ELSE 4 END)
                - LEAST(2, GREATEST(0, FLOOR(EXTRACT(EPOCH FROM (NOW() - COALESCE(c.queued_at, c.created_at))) / 1800)::int)))
        END,
        -- Within a class, the tenant with the fewest platform jobs in flight
        -- first: shared sensors are shared fairly across tenants.
        COALESCE(load.in_flight, 0),
        c.queue_priority DESC,
        c.queued_at ASC
    LIMIT 1
    FOR UPDATE OF c SKIP LOCKED;

    IF v_command_id IS NULL THEN
        RETURN;
    END IF;

    UPDATE commands
    SET platform_sensor_id = p_sensor_id,
        status = 'acknowledged',
        acknowledged_at = NOW(),
        dispatch_attempts = dispatch_attempts + 1
    WHERE id = v_command_id;

    RETURN QUERY SELECT v_command_id, v_tenant_id, v_command_type, v_payload, v_queued_at, v_auth_token_prefix;
END;
$$;


--
-- Name: mark_finding_regression(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_finding_regression() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Only "we fixed it and it came back" counts. Closed dispositions
    -- (false_positive, accepted, accepted_risk, duplicate) are triage
    -- corrections, and not_observed is "not seen lately", not a fix that failed.
    IF OLD.status IN ('resolved', 'verified')
       AND NEW.status NOT IN ('resolved', 'verified', 'false_positive', 'accepted', 'accepted_risk', 'duplicate', 'not_observed')
    THEN
        NEW.is_regression    := TRUE;
        NEW.reopen_count     := COALESCE(OLD.reopen_count, 0) + 1;
        NEW.last_reopened_at := NOW();
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: merge_jsonb_arrays_by_key(jsonb, jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_jsonb_arrays_by_key(base jsonb, new_data jsonb, unique_keys text[]) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    result JSONB;
    elem JSONB;
    existing_keys TEXT[];
    elem_key TEXT;
    key_parts TEXT[];
BEGIN
    -- Handle nulls
    IF base IS NULL THEN RETURN new_data; END IF;
    IF new_data IS NULL THEN RETURN base; END IF;

    -- Start with base array
    result := base;
    existing_keys := ARRAY[]::TEXT[];

    -- Build list of existing unique keys from base
    FOR elem IN SELECT jsonb_array_elements(base)
    LOOP
        key_parts := ARRAY[]::TEXT[];
        FOR i IN 1..array_length(unique_keys, 1)
        LOOP
            key_parts := array_append(key_parts, COALESCE(elem->>unique_keys[i], ''));
        END LOOP;
        existing_keys := array_append(existing_keys, array_to_string(key_parts, ':'));
    END LOOP;

    -- Add non-duplicate elements from new_data
    FOR elem IN SELECT jsonb_array_elements(new_data)
    LOOP
        key_parts := ARRAY[]::TEXT[];
        FOR i IN 1..array_length(unique_keys, 1)
        LOOP
            key_parts := array_append(key_parts, COALESCE(elem->>unique_keys[i], ''));
        END LOOP;
        elem_key := array_to_string(key_parts, ':');

        IF NOT elem_key = ANY(existing_keys) THEN
            result := result || jsonb_build_array(elem);
            existing_keys := array_append(existing_keys, elem_key);
        END IF;
    END LOOP;

    RETURN result;
END;
$$;


--
-- Name: FUNCTION merge_jsonb_arrays_by_key(base jsonb, new_data jsonb, unique_keys text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.merge_jsonb_arrays_by_key(base jsonb, new_data jsonb, unique_keys text[]) IS 'Merges two JSONB arrays, deduplicating by composite unique key. Used for recon data merging.';


--
-- Name: merge_jsonb_deep(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_jsonb_deep(base jsonb, new_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    result JSONB;
    key TEXT;
    base_val JSONB;
    new_data_val JSONB;
BEGIN
    -- Handle nulls
    IF base IS NULL THEN RETURN new_data; END IF;
    IF new_data IS NULL THEN RETURN base; END IF;

    -- Start with base
    result := base;

    -- Iterate through new_data keys
    FOR key IN SELECT jsonb_object_keys(new_data)
    LOOP
        base_val := result->key;
        new_data_val := new_data->key;

        -- Handle different merge strategies based on key name
        IF key IN ('dns_records') THEN
            -- DNS records: dedupe by (type, name, value)
            result := jsonb_set(
                result,
                ARRAY[key],
                merge_jsonb_arrays_by_key(base_val, new_data_val, ARRAY['type', 'name', 'value'])
            );
        ELSIF key IN ('ports') THEN
            -- Ports: dedupe by (port, protocol)
            result := jsonb_set(
                result,
                ARRAY[key],
                merge_jsonb_arrays_by_key(base_val, new_data_val, ARRAY['port', 'protocol'])
            );
        ELSIF key IN ('technologies', 'nameservers', 'sans') THEN
            -- Simple string arrays: union unique
            IF jsonb_typeof(base_val) = 'array' AND jsonb_typeof(new_data_val) = 'array' THEN
                result := jsonb_set(
                    result,
                    ARRAY[key],
                    (SELECT jsonb_agg(DISTINCT value) FROM (
                        SELECT value FROM jsonb_array_elements(base_val)
                        UNION
                        SELECT value FROM jsonb_array_elements(new_data_val)
                    ) t)
                );
            ELSE
                result := jsonb_set(result, ARRAY[key], new_data_val);
            END IF;
        ELSIF jsonb_typeof(base_val) = 'object' AND jsonb_typeof(new_data_val) = 'object' THEN
            -- Nested objects: recursive merge
            result := jsonb_set(result, ARRAY[key], merge_jsonb_deep(base_val, new_data_val));
        ELSE
            -- Scalars and other: new_data wins
            result := jsonb_set(result, ARRAY[key], new_data_val);
        END IF;
    END LOOP;

    RETURN result;
END;
$$;


--
-- Name: FUNCTION merge_jsonb_deep(base jsonb, new_data jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.merge_jsonb_deep(base jsonb, new_data jsonb) IS 'Deep merges two JSONB objects with intelligent array deduplication for recon data fields.';


--
-- Name: prevent_audit_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_audit_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.changed_by IS NOT NULL
       AND NEW.changed_by IS NULL
       AND (to_jsonb(NEW) - 'changed_by') = (to_jsonb(OLD) - 'changed_by')
       AND NOT EXISTS (SELECT 1 FROM users WHERE id = OLD.changed_by) THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'UPDATE on asset_state_history is not allowed. Audit records are immutable. Insert a new record instead.';
    RETURN NULL;
END;
$$;


--
-- Name: prevent_recent_audit_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_recent_audit_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.changed_at > NOW() - INTERVAL '30 days'
       AND EXISTS (SELECT 1 FROM assets WHERE id = OLD.asset_id)
       AND EXISTS (SELECT 1 FROM tenants WHERE id = OLD.tenant_id) THEN
        RAISE EXCEPTION 'Cannot delete asset_state_history records less than 30 days old (changed_at: %). Use retention jobs for cleanup.', OLD.changed_at;
        RETURN NULL;
    END IF;
    RETURN OLD;
END;
$$;


--
-- Name: principal_is_active(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.principal_is_active(p_tenant_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM tenant_members tm
        JOIN users u ON u.id = tm.user_id
        WHERE tm.tenant_id = p_tenant_id
          AND tm.user_id = p_user_id
          AND tm.status = 'active'
          AND u.status = 'active'
    );
$$;


--
-- Name: promote_branch_only_findings(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.promote_branch_only_findings(p_tenant_id uuid, p_finding_ids uuid[]) RETURNS SETOF uuid
    LANGUAGE sql
    AS $$
    UPDATE findings f
    SET branch_only = FALSE,
        sla_deadline = f.sla_deadline + (NOW() - COALESCE(f.first_detected_at, f.created_at)),
        sla_status = CASE WHEN f.sla_deadline IS NULL THEN f.sla_status ELSE 'on_track' END,
        updated_at = NOW()
    WHERE f.tenant_id = p_tenant_id
      AND f.id = ANY(p_finding_ids)
      AND f.branch_only
      AND EXISTS (SELECT 1 FROM finding_branch_occurrences o
                  WHERE o.tenant_id = p_tenant_id AND o.finding_id = f.id
                    AND branch_counts_as_exposure(o.branch_id))
    RETURNING f.id
$$;


--
-- Name: recover_stuck_platform_jobs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_stuck_platform_jobs(p_stuck_threshold_minutes integer) RETURNS integer
    LANGUAGE sql
    AS $$
    SELECT recover_stuck_platform_jobs(p_stuck_threshold_minutes, 3);
$$;


--
-- Name: recover_stuck_platform_jobs(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_stuck_platform_jobs(p_stuck_threshold_minutes integer, p_max_retries integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    recovered_count INTEGER;
BEGIN
    WITH stuck_jobs AS (
        UPDATE commands
        SET platform_sensor_id = NULL,
            sensor_id = NULL,
            status = 'pending',
            -- Clearing acknowledged_at keeps the row honest once it is back in
            -- the queue; ClaimForSensor sets it again on the next claim.
            acknowledged_at = NULL,
            -- Count each recovery as a dispatch attempt. Without this the
            -- counter never moves for a platform job and fail_exhausted_commands
            -- (dispatch_attempts >= p_max_retries) can never take over.
            dispatch_attempts = dispatch_attempts + 1
        WHERE is_platform_job = TRUE
        AND status = 'acknowledged'
        -- Claimed by *either* dispatch path: platform_sensor_id is what
        -- get_next_platform_job would set, sensor_id is what the poll path
        -- actually sets today.
        AND (platform_sensor_id IS NOT NULL OR sensor_id IS NOT NULL)
        AND acknowledged_at < NOW() - (p_stuck_threshold_minutes || ' minutes')::INTERVAL
        AND dispatch_attempts < p_max_retries
        RETURNING id
    )
    SELECT COUNT(*) INTO recovered_count FROM stuck_jobs;

    RETURN recovered_count;
END;
$$;


--
-- Name: recover_stuck_tenant_commands(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_stuck_tenant_commands(p_stuck_threshold_minutes integer, p_max_retries integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    recovered_count INTEGER;
BEGIN
    WITH stuck_commands AS (
        UPDATE commands
        SET sensor_id = NULL,
            status = 'pending',
            -- Tenant commands have no other dispatch-attempt accounting, so
            -- count each recovery as an attempt. This gives the max_retries
            -- guard a stopping condition and lets fail_exhausted_commands take
            -- over once the command is exhausted.
            dispatch_attempts = dispatch_attempts + 1
        WHERE is_platform_job = FALSE
        AND status = 'acknowledged'
        AND sensor_id IS NOT NULL
        AND acknowledged_at < NOW() - (p_stuck_threshold_minutes || ' minutes')::INTERVAL
        AND dispatch_attempts < p_max_retries
        AND lease_expires_at IS NULL
        RETURNING id
    )
    SELECT COUNT(*) INTO recovered_count FROM stuck_commands;

    RETURN recovered_count;
END;
$$;


--
-- Name: refresh_access_for_asset_assign(uuid, uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_access_for_asset_assign(p_group_id uuid, p_asset_id uuid, p_ownership_type character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO user_accessible_assets (user_id, tenant_id, asset_id, ownership_type)
    SELECT gm.user_id, g.tenant_id, a.id, p_ownership_type
    FROM group_members gm
    JOIN groups g ON g.id = gm.group_id AND g.is_active = TRUE
    JOIN assets a ON a.id = p_asset_id AND a.tenant_id = g.tenant_id
    WHERE gm.group_id = p_group_id
      AND principal_is_active(g.tenant_id, gm.user_id)
    ON CONFLICT (user_id, tenant_id, asset_id) DO NOTHING;
END;
$$;


--
-- Name: refresh_access_for_asset_unassign(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_access_for_asset_unassign(p_group_id uuid, p_asset_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM user_accessible_assets uaa
    WHERE uaa.asset_id = p_asset_id
      AND uaa.user_id IN (
          SELECT gm.user_id FROM group_members gm WHERE gm.group_id = p_group_id
      )
      AND NOT EXISTS (
          SELECT 1
          FROM group_members gm2
          JOIN groups g2 ON g2.id = gm2.group_id AND g2.is_active = TRUE
          JOIN asset_owners ao2 ON ao2.group_id = gm2.group_id AND ao2.asset_id = p_asset_id
          WHERE gm2.user_id = uaa.user_id
            AND gm2.group_id != p_group_id
      )
      AND NOT EXISTS (
          SELECT 1 FROM asset_access_grants aag
          WHERE aag.asset_id = p_asset_id AND aag.user_id = uaa.user_id
      );
END;
$$;


--
-- Name: refresh_access_for_grant_add(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_access_for_grant_add(p_asset_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO user_accessible_assets (user_id, tenant_id, asset_id, ownership_type)
    SELECT aag.user_id, aag.tenant_id, aag.asset_id, 'secondary'
    FROM asset_access_grants aag
    WHERE aag.asset_id = p_asset_id AND aag.user_id = p_user_id
      AND principal_is_active(aag.tenant_id, aag.user_id)
    ON CONFLICT (user_id, tenant_id, asset_id) DO NOTHING;
END;
$$;


--
-- Name: refresh_access_for_grant_remove(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_access_for_grant_remove(p_asset_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM user_accessible_assets uaa
    WHERE uaa.user_id = p_user_id AND uaa.asset_id = p_asset_id
      AND NOT EXISTS (
          SELECT 1 FROM group_members gm
          JOIN groups g ON g.id = gm.group_id AND g.is_active = TRUE
          JOIN asset_owners ao ON ao.group_id = gm.group_id AND ao.asset_id = p_asset_id
          WHERE gm.user_id = p_user_id)
      AND NOT EXISTS (
          SELECT 1 FROM asset_access_grants aag
          WHERE aag.asset_id = p_asset_id AND aag.user_id = p_user_id);
END;
$$;


--
-- Name: refresh_access_for_member_add(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_access_for_member_add(p_group_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO user_accessible_assets (user_id, tenant_id, asset_id, ownership_type)
    SELECT p_user_id, g.tenant_id, ao.asset_id, ao.ownership_type
    FROM asset_owners ao
    JOIN groups g ON g.id = ao.group_id AND g.is_active = TRUE
    JOIN assets a ON a.id = ao.asset_id AND a.tenant_id = g.tenant_id
    WHERE ao.group_id = p_group_id
      AND principal_is_active(g.tenant_id, p_user_id)
    ON CONFLICT (user_id, tenant_id, asset_id) DO NOTHING;
END;
$$;


--
-- Name: refresh_access_for_member_remove(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_access_for_member_remove(p_group_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM user_accessible_assets uaa
    WHERE uaa.user_id = p_user_id
      AND uaa.asset_id IN (
          SELECT ao.asset_id FROM asset_owners ao WHERE ao.group_id = p_group_id
      )
      AND NOT EXISTS (
          SELECT 1
          FROM group_members gm2
          JOIN groups g2 ON g2.id = gm2.group_id AND g2.is_active = TRUE
          JOIN asset_owners ao2 ON ao2.group_id = gm2.group_id AND ao2.asset_id = uaa.asset_id
          WHERE gm2.user_id = p_user_id
            AND gm2.group_id != p_group_id
      )
      AND NOT EXISTS (
          SELECT 1 FROM asset_access_grants aag
          WHERE aag.asset_id = uaa.asset_id AND aag.user_id = p_user_id
      );
END;
$$;


--
-- Name: refresh_access_for_user(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_access_for_user(p_tenant_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM user_accessible_assets
    WHERE tenant_id = p_tenant_id AND user_id = p_user_id;

    IF NOT principal_is_active(p_tenant_id, p_user_id) THEN
        RETURN;
    END IF;

    INSERT INTO user_accessible_assets (user_id, tenant_id, asset_id, ownership_type)
    SELECT DISTINCT gm.user_id, g.tenant_id, ao.asset_id, ao.ownership_type
    FROM group_members gm
    JOIN groups g ON g.id = gm.group_id AND g.is_active = TRUE AND g.tenant_id = p_tenant_id
    JOIN asset_owners ao ON ao.group_id = gm.group_id
    JOIN assets a ON a.id = ao.asset_id AND a.tenant_id = g.tenant_id
    WHERE gm.user_id = p_user_id
    UNION
    SELECT DISTINCT aag.user_id, aag.tenant_id, aag.asset_id, 'secondary'
    FROM asset_access_grants aag
    WHERE aag.tenant_id = p_tenant_id AND aag.user_id = p_user_id
    ON CONFLICT (user_id, tenant_id, asset_id) DO NOTHING;
END;
$$;


--
-- Name: refresh_user_accessible_assets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_user_accessible_assets() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM user_accessible_assets;
    INSERT INTO user_accessible_assets (user_id, tenant_id, asset_id, ownership_type)
    SELECT DISTINCT gm.user_id, g.tenant_id, ao.asset_id, ao.ownership_type
    FROM group_members gm
    JOIN groups g ON g.id = gm.group_id AND g.is_active = TRUE
    JOIN asset_owners ao ON ao.group_id = gm.group_id
    JOIN assets a ON a.id = ao.asset_id AND a.tenant_id = g.tenant_id
    WHERE principal_is_active(g.tenant_id, gm.user_id)
    UNION
    SELECT DISTINCT aag.user_id, aag.tenant_id, aag.asset_id, 'secondary'
    FROM asset_access_grants aag
    WHERE principal_is_active(aag.tenant_id, aag.user_id)
    ON CONFLICT (user_id, tenant_id, asset_id) DO NOTHING;
END;
$$;


--
-- Name: refuse_admin_only_permission_on_custom_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refuse_admin_only_permission_on_custom_role() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.permission_id IN ('sensors:write', 'sensors:delete', 'sensors:commands:delete',
                             'sensors:zones:write', 'sensors:zones:delete',
                             'scans:ci:write', 'scans:ci:override',
                             'sensors:pair', 'sensors:approve', 'sensors:grant:narrow',
                             'sensors:grant:widen', 'sensors:revoke')
       AND EXISTS (SELECT 1 FROM roles WHERE id = NEW.role_id AND tenant_id IS NOT NULL) THEN
        RAISE EXCEPTION 'permission % is reserved for the owner and admin roles and cannot be put on a custom role',
            NEW.permission_id
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: repository_branches_promote_branch_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repository_branches_promote_branch_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    t RECORD;
BEGIN
    IF NOT branch_counts_as_exposure(NEW.id) THEN
        RETURN NULL;
    END IF;
    FOR t IN
        SELECT o.tenant_id, array_agg(o.finding_id) AS ids
        FROM finding_branch_occurrences o
        JOIN findings f ON f.id = o.finding_id AND f.tenant_id = o.tenant_id AND f.branch_only
        WHERE o.branch_id = NEW.id
        GROUP BY o.tenant_id
    LOOP
        PERFORM promote_branch_only_findings(t.tenant_id, t.ids);
    END LOOP;
    RETURN NULL;
END;
$$;


--
-- Name: sensor_effective_list(text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sensor_effective_list(declared text[], reported text[]) RETURNS text[]
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    SELECT CASE
        WHEN reported IS NULL THEN COALESCE(declared, '{}'::text[])
        WHEN COALESCE(cardinality(declared), 0) = 0 THEN reported
        ELSE ARRAY(
            SELECT r.v FROM unnest(reported) WITH ORDINALITY AS r(v, i)
            WHERE r.v = ANY(declared)
            ORDER BY r.i
        )
    END
$$;


--
-- Name: sensor_effective_max_jobs(integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sensor_effective_max_jobs(admin integer, reported integer, capacity jsonb) RETURNS integer
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    SELECT COALESCE(
        (SELECT min(v) FROM unnest(ARRAY[
            admin,
            reported,
            CASE WHEN jsonb_typeof(capacity->'slots_total') = 'number'
                 THEN LEAST(GREATEST(floor((capacity->>'slots_total')::numeric), 0), 100)::integer
            END
        ]) AS v WHERE v > 0),
        admin)
$$;


--
-- Name: sensor_grants_default(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sensor_grants_default() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.is_platform_sensor THEN
        UPDATE sensors SET trust_level = 'trusted' WHERE id = NEW.id;
        INSERT INTO sensor_grants (sensor_id, tenant_id, profile, tier_ceiling, target_network,
                                   allow_credentials, allow_push_ingest, remote_actions)
        VALUES (NEW.id, NEW.tenant_id, 'legacy-broad', 2, 'any', TRUE, TRUE,
                ARRAY['diagnostics', 'rotate_key', 'update'])
        ON CONFLICT (sensor_id) DO NOTHING;
    ELSE
        INSERT INTO sensor_grants (sensor_id, tenant_id, profile, job_types, tier_ceiling, target_network)
        VALUES (NEW.id, NEW.tenant_id, 'internal-network-scanner', ARRAY['scan', 'validate'], 1, 'any')
        ON CONFLICT (sensor_id) DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: sync_tenant_member_delete_to_user_roles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_tenant_member_delete_to_user_roles() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- When a tenant_member is deleted, remove all their roles in that tenant
    DELETE FROM user_roles
    WHERE user_id = OLD.user_id
      AND tenant_id = OLD.tenant_id;

    RETURN OLD;
END;
$$;


--
-- Name: sync_tenant_member_to_user_roles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_tenant_member_to_user_roles() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_role_id UUID;
BEGIN
    -- Get the system role ID based on role slug
    SELECT id INTO v_role_id
    FROM roles
    WHERE slug = NEW.role
      AND is_system = TRUE
      AND tenant_id IS NULL;

    IF v_role_id IS NULL THEN
        -- If role not found, log warning but don't fail
        RAISE WARNING 'Role % not found in roles table, skipping user_roles sync', NEW.role;
        RETURN NEW;
    END IF;

    IF TG_OP = 'INSERT' THEN
        -- Insert into user_roles if not exists
        INSERT INTO user_roles (user_id, tenant_id, role_id, assigned_at, assigned_by)
        VALUES (NEW.user_id, NEW.tenant_id, v_role_id, NEW.joined_at, NEW.invited_by)
        ON CONFLICT (user_id, tenant_id, role_id) DO NOTHING;

    ELSIF TG_OP = 'UPDATE' THEN
        -- If role changed, remove old role and add new one
        IF OLD.role != NEW.role THEN
            -- Get old role ID
            DECLARE
                v_old_role_id UUID;
            BEGIN
                SELECT id INTO v_old_role_id
                FROM roles
                WHERE slug = OLD.role
                  AND is_system = TRUE
                  AND tenant_id IS NULL;

                -- Remove old role
                IF v_old_role_id IS NOT NULL THEN
                    DELETE FROM user_roles
                    WHERE user_id = NEW.user_id
                      AND tenant_id = NEW.tenant_id
                      AND role_id = v_old_role_id;
                END IF;

                -- Add new role
                INSERT INTO user_roles (user_id, tenant_id, role_id, assigned_at)
                VALUES (NEW.user_id, NEW.tenant_id, v_role_id, NOW())
                ON CONFLICT (user_id, tenant_id, role_id) DO NOTHING;
            END;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: trg_asset_owners_scope_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_asset_owners_scope_sync() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.group_id IS NOT NULL THEN
            PERFORM refresh_access_for_asset_assign(NEW.group_id, NEW.asset_id, NEW.ownership_type);
        END IF;
        RETURN NEW;
    END IF;
    -- DELETE
    IF OLD.group_id IS NOT NULL THEN
        PERFORM refresh_access_for_asset_unassign(OLD.group_id, OLD.asset_id);
    END IF;
    RETURN OLD;
END;
$$;


--
-- Name: trg_group_members_scope_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_group_members_scope_sync() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM refresh_access_for_member_remove(OLD.group_id, OLD.user_id);
    RETURN OLD;
END;
$$;


--
-- Name: trg_groups_active_scope_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_groups_active_scope_sync() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    m RECORD;
BEGIN
    FOR m IN SELECT gm.user_id FROM group_members gm WHERE gm.group_id = NEW.id LOOP
        PERFORM refresh_access_for_user(NEW.tenant_id, m.user_id);
    END LOOP;
    RETURN NEW;
END;
$$;


--
-- Name: trg_groups_delete_scope_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_groups_delete_scope_sync() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM asset_owners WHERE group_id = OLD.id;
    RETURN OLD;
END;
$$;


--
-- Name: trg_scope_rule_scope_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_scope_rule_scope_sync() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM asset_owners WHERE scope_rule_id = OLD.id;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: update_branch_finding_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_branch_finding_counts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_branch_id UUID;
BEGIN
  -- Determine which branch_id to update
  IF TG_OP = 'DELETE' THEN
    target_branch_id := OLD.branch_id;
  ELSIF TG_OP = 'UPDATE' THEN
    -- Update both old and new branch if changed
    IF OLD.branch_id IS DISTINCT FROM NEW.branch_id THEN
      IF OLD.branch_id IS NOT NULL THEN
        UPDATE repository_branches SET
          findings_total = COALESCE((SELECT COUNT(*) FROM findings WHERE branch_id = OLD.branch_id AND status NOT IN ('resolved','false_positive')), 0),
          findings_critical = COALESCE((SELECT COUNT(*) FROM findings WHERE branch_id = OLD.branch_id AND severity = 'critical' AND status NOT IN ('resolved','false_positive')), 0),
          findings_high = COALESCE((SELECT COUNT(*) FROM findings WHERE branch_id = OLD.branch_id AND severity = 'high' AND status NOT IN ('resolved','false_positive')), 0),
          findings_medium = COALESCE((SELECT COUNT(*) FROM findings WHERE branch_id = OLD.branch_id AND severity = 'medium' AND status NOT IN ('resolved','false_positive')), 0),
          findings_low = COALESCE((SELECT COUNT(*) FROM findings WHERE branch_id = OLD.branch_id AND severity = 'low' AND status NOT IN ('resolved','false_positive')), 0)
        WHERE id = OLD.branch_id
          AND EXISTS (SELECT 1 FROM asset_repositories ar WHERE ar.asset_id = repository_branches.repository_id);
      END IF;
    END IF;
    target_branch_id := NEW.branch_id;
  ELSE
    target_branch_id := NEW.branch_id;
  END IF;

  -- Update target branch counts
  IF target_branch_id IS NOT NULL THEN
    UPDATE repository_branches SET
      findings_total = COALESCE((SELECT COUNT(*) FROM findings WHERE branch_id = target_branch_id AND status NOT IN ('resolved','false_positive')), 0),
      findings_critical = COALESCE((SELECT COUNT(*) FROM findings WHERE branch_id = target_branch_id AND severity = 'critical' AND status NOT IN ('resolved','false_positive')), 0),
      findings_high = COALESCE((SELECT COUNT(*) FROM findings WHERE branch_id = target_branch_id AND severity = 'high' AND status NOT IN ('resolved','false_positive')), 0),
      findings_medium = COALESCE((SELECT COUNT(*) FROM findings WHERE branch_id = target_branch_id AND severity = 'medium' AND status NOT IN ('resolved','false_positive')), 0),
      findings_low = COALESCE((SELECT COUNT(*) FROM findings WHERE branch_id = target_branch_id AND severity = 'low' AND status NOT IN ('resolved','false_positive')), 0)
    WHERE id = target_branch_id
      AND EXISTS (SELECT 1 FROM asset_repositories ar WHERE ar.asset_id = repository_branches.repository_id);
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: update_finding_comments_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_finding_comments_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE findings
        SET comments_count = comments_count + 1,
            updated_at = NOW()
        WHERE id = NEW.finding_id;
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE findings
        SET comments_count = GREATEST(comments_count - 1, 0),
            updated_at = NOW()
        WHERE id = OLD.finding_id;
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: FUNCTION update_finding_comments_count(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_finding_comments_count() IS 'Keeps findings.comments_count in sync when comments are added/deleted';


--
-- Name: update_repository_branch_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_repository_branch_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_repo_id UUID;
BEGIN
  target_repo_id := COALESCE(NEW.repository_id, OLD.repository_id);

  UPDATE asset_repositories SET
    branch_count = (SELECT COUNT(*) FROM repository_branches WHERE repository_id = target_repo_id),
    protected_branch_count = (SELECT COUNT(*) FROM repository_branches WHERE repository_id = target_repo_id AND is_protected = true)
  WHERE asset_id = target_repo_id;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: update_repository_component_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_repository_component_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_asset_id UUID;
BEGIN
  target_asset_id := COALESCE(NEW.asset_id, OLD.asset_id);

  UPDATE asset_repositories SET
    component_count = (SELECT COUNT(*) FROM asset_components WHERE asset_id = target_asset_id),
    vulnerable_component_count = (SELECT COUNT(*) FROM asset_components WHERE asset_id = target_asset_id AND has_known_vulnerabilities = true)
  WHERE asset_id = target_asset_id;

  RETURN COALESCE(NEW, OLD);
END;
$$;


