--
-- Name: uuid_generate_v7(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uuid_generate_v7() RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    unix_ts_ms BIGINT;
    buffer BYTEA;
BEGIN
    unix_ts_ms = (EXTRACT(EPOCH FROM clock_timestamp()) * 1000)::BIGINT;
    -- Start with 16 zero bytes
    buffer = E'\\x00000000000000000000000000000000'::bytea;
    -- Set timestamp (first 6 bytes = 48 bits)
    -- Must mask BEFORE casting to int to avoid integer overflow
    buffer = set_byte(buffer, 0, ((unix_ts_ms >> 40) & 255)::int);
    buffer = set_byte(buffer, 1, ((unix_ts_ms >> 32) & 255)::int);
    buffer = set_byte(buffer, 2, ((unix_ts_ms >> 24) & 255)::int);
    buffer = set_byte(buffer, 3, ((unix_ts_ms >> 16) & 255)::int);
    buffer = set_byte(buffer, 4, ((unix_ts_ms >> 8) & 255)::int);
    buffer = set_byte(buffer, 5, (unix_ts_ms & 255)::int);
    -- Fill remaining 10 bytes with random data
    buffer = overlay(buffer PLACING gen_random_bytes(10) FROM 7);
    -- Set version to 7 (bits 48-51 = 0111)
    buffer = set_byte(buffer, 6, (get_byte(buffer, 6) & 15) | (7 << 4));
    -- Set variant to RFC 4122 (bits 64-65 = 10)
    buffer = set_byte(buffer, 8, (get_byte(buffer, 8) & 63) | 128);
    RETURN encode(buffer, 'hex')::uuid;
END
$$;


--
-- Name: FUNCTION uuid_generate_v7(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.uuid_generate_v7() IS 'Generates RFC 9562 UUID v7 (time-sortable, ms precision timestamp + random)';


--
-- Name: vulnerabilities_definition_compat(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.vulnerabilities_definition_compat() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.tenant_id IS DISTINCT FROM OLD.tenant_id THEN
        RAISE EXCEPTION 'the scope of definition % cannot change', OLD.id
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.cve_id IS NOT NULL AND NEW.external_id IS NULL THEN
        NEW.external_id := NEW.cve_id;
    END IF;
    NEW.scope_tenant_id := COALESCE(NEW.tenant_id, '00000000-0000-0000-0000-000000000000'::uuid);
    RETURN NEW;
END;
$$;


--
-- Name: vulnerabilities_primary_identifier(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.vulnerabilities_primary_identifier() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO definition_identifiers
        (namespace, external_id, tenant_id, scope_tenant_id, definition_id, is_primary, asserted_by)
    SELECT n.namespace, n.external_id, n.tenant_id, n.scope_tenant_id, n.id, TRUE, n.origin
    FROM new_definitions n
    WHERE n.external_id IS NOT NULL
    ON CONFLICT DO NOTHING;
    RETURN NULL;
END;
$$;



