--
-- Name: assets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.assets (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    tenant_id uuid NOT NULL,
    name character varying(255) NOT NULL,
    asset_type character varying(50) NOT NULL,
    criticality character varying(20) DEFAULT 'medium'::character varying NOT NULL,
    status character varying(20) DEFAULT 'active'::character varying NOT NULL,
    description text,
    scope character varying(20) DEFAULT 'internal'::character varying NOT NULL,
    exposure character varying(20) DEFAULT 'unknown'::character varying NOT NULL,
    risk_score integer DEFAULT 0 NOT NULL,
    first_seen timestamp with time zone DEFAULT now() NOT NULL,
    last_seen timestamp with time zone DEFAULT now() NOT NULL,
    tags text[] DEFAULT '{}'::text[],
    properties jsonb DEFAULT '{}'::jsonb NOT NULL,
    provider character varying(50),
    external_id character varying(255),
    sync_status character varying(20) DEFAULT 'synced'::character varying NOT NULL,
    last_synced_at timestamp with time zone,
    sync_error text,
    classification character varying(50),
    parent_id uuid,
    data_classification character varying(50),
    compliance_scope text[] DEFAULT '{}'::text[],
    pii_data_exposed boolean DEFAULT false,
    phi_data_exposed boolean DEFAULT false,
    regulatory_owner_id uuid,
    is_internet_accessible boolean DEFAULT false,
    exposure_changed_at timestamp with time zone,
    last_exposure_level character varying(50),
    source_type character varying(50) DEFAULT 'manual'::character varying,
    discovered_at timestamp with time zone DEFAULT now(),
    discovery_source character varying(50),
    discovery_tool character varying(50),
    integration_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    owner_ref character varying(500),
    is_crown_jewel boolean DEFAULT false NOT NULL,
    business_impact_score numeric(5,2) DEFAULT 0,
    business_impact_notes text DEFAULT ''::text,
    sub_type character varying(50),
    environment character varying(20),
    lifecycle_paused_until timestamp with time zone,
    manual_status_override boolean DEFAULT false NOT NULL,
    impact_confidentiality character varying(10),
    impact_integrity character varying(10),
    impact_availability character varying(10),
    asset_class character varying(32),
    asset_lens character varying(32),
    deleted_at timestamp with time zone,
    deleted_by uuid,
    import_id uuid,
    CONSTRAINT assets_environment_check CHECK (((environment IS NULL) OR ((environment)::text = ANY ((ARRAY['production'::character varying, 'staging'::character varying, 'development'::character varying, 'testing'::character varying, 'dr'::character varying])::text[])))),
    CONSTRAINT check_compliance_scope_size CHECK (((compliance_scope IS NULL) OR (array_length(compliance_scope, 1) <= 20))),
    CONSTRAINT check_exposure_changed_at_not_future CHECK (((exposure_changed_at IS NULL) OR (exposure_changed_at <= (now() + '00:01:00'::interval)))),
    CONSTRAINT chk_assets_core_type CHECK (((asset_type)::text = ANY ((ARRAY['domain'::character varying, 'subdomain'::character varying, 'ip_address'::character varying, 'certificate'::character varying, 'service'::character varying, 'application'::character varying, 'host'::character varying, 'cloud_account'::character varying, 'container'::character varying, 'kubernetes'::character varying, 'repository'::character varying, 'identity'::character varying, 'database'::character varying, 'storage'::character varying, 'network'::character varying, 'unclassified'::character varying])::text[]))),
    CONSTRAINT chk_assets_criticality CHECK (((criticality)::text = ANY ((ARRAY['low'::character varying, 'medium'::character varying, 'high'::character varying, 'critical'::character varying])::text[]))),
    CONSTRAINT chk_assets_data_classification CHECK (((data_classification IS NULL) OR ((data_classification)::text = ANY ((ARRAY['public'::character varying, 'internal'::character varying, 'confidential'::character varying, 'restricted'::character varying, 'secret'::character varying])::text[])))),
    CONSTRAINT chk_assets_exposure CHECK (((exposure)::text = ANY ((ARRAY['public'::character varying, 'restricted'::character varying, 'private'::character varying, 'isolated'::character varying, 'unknown'::character varying])::text[]))),
    CONSTRAINT chk_assets_impact_availability CHECK (((impact_availability IS NULL) OR ((impact_availability)::text = ANY ((ARRAY['low'::character varying, 'moderate'::character varying, 'high'::character varying])::text[])))),
    CONSTRAINT chk_assets_impact_confidentiality CHECK (((impact_confidentiality IS NULL) OR ((impact_confidentiality)::text = ANY ((ARRAY['low'::character varying, 'moderate'::character varying, 'high'::character varying])::text[])))),
    CONSTRAINT chk_assets_impact_integrity CHECK (((impact_integrity IS NULL) OR ((impact_integrity)::text = ANY ((ARRAY['low'::character varying, 'moderate'::character varying, 'high'::character varying])::text[])))),
    CONSTRAINT chk_assets_last_exposure_level CHECK (((last_exposure_level IS NULL) OR ((last_exposure_level)::text = ANY ((ARRAY['public'::character varying, 'restricted'::character varying, 'private'::character varying, 'isolated'::character varying, 'unknown'::character varying])::text[])))),
    CONSTRAINT chk_assets_risk_score CHECK (((risk_score >= 0) AND (risk_score <= 100))),
    CONSTRAINT chk_assets_scope CHECK (((scope)::text = ANY ((ARRAY['internal'::character varying, 'external'::character varying, 'cloud'::character varying, 'partner'::character varying, 'vendor'::character varying, 'shadow'::character varying])::text[]))),
    CONSTRAINT chk_assets_source_type CHECK (((source_type IS NULL) OR ((source_type)::text = ANY ((ARRAY['manual'::character varying, 'integration'::character varying, 'discovery'::character varying, 'import'::character varying, 'api'::character varying, 'sensor'::character varying, 'scan'::character varying])::text[])))),
    CONSTRAINT chk_assets_status CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'stale'::character varying, 'inactive'::character varying, 'archived'::character varying])::text[]))),
    CONSTRAINT chk_assets_sync_status CHECK (((sync_status)::text = ANY ((ARRAY['synced'::character varying, 'pending'::character varying, 'syncing'::character varying, 'error'::character varying, 'disabled'::character varying])::text[])))
);


