-- Name: COLUMN assets.impact_integrity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.assets.impact_integrity IS 'CTEM Scoping CIA impact rating: low|moderate|high (NULL = not rated)';


--
-- Name: COLUMN assets.impact_availability; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.assets.impact_availability IS 'CTEM Scoping CIA impact rating: low|moderate|high (NULL = not rated)';


