-- Name: COLUMN assets.asset_class; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.assets.asset_class IS 'RFC-042 class, derived from (asset_type, sub_type) by trg_assets_registry_class; never written by the app';


