    CONSTRAINT attacker_profiles_profile_type_check CHECK (((profile_type)::text = ANY ((ARRAY['external_unauth'::character varying, 'external_stolen_creds'::character varying, 'malicious_insider'::character varying, 'supplier_compromise'::character varying, 'custom'::character varying])::text[])))
);


