    CONSTRAINT chk_audit_anchor_archive_hex CHECK (((archive_sha256)::text ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT chk_audit_anchor_count CHECK ((pruned_count > 0)),
    CONSTRAINT chk_audit_anchor_hash_hex CHECK (((anchor_hash)::text ~ '^[0-9a-f]{64}$'::text))
);


