    new_hash character varying(64) NOT NULL,
    CONSTRAINT chk_audit_chain_rb_new_hash CHECK (((new_hash)::text ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT chk_audit_chain_rb_new_prev CHECK ((((new_prev_hash)::text = ''::text) OR ((new_prev_hash)::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT chk_audit_chain_rb_old_hash CHECK (((old_hash)::text ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT chk_audit_chain_rb_old_prev CHECK ((((old_prev_hash)::text = ''::text) OR ((old_prev_hash)::text ~ '^[0-9a-f]{64}$'::text)))
);


