--
-- Name: ci_gate_policies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ci_gate_policies (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    scope_type character varying(20) NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    mode character varying(10) DEFAULT 'enforce'::character varying NOT NULL,
    fail_on_severity character varying(10) DEFAULT 'high'::character varying NOT NULL,
    new_findings_only boolean DEFAULT true NOT NULL,
    fail_on_kev boolean DEFAULT true NOT NULL,
    epss_threshold numeric(5,4),
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    repository_asset_id uuid,
    business_unit_id uuid,
    CONSTRAINT chk_ci_gate_policies_epss CHECK (((epss_threshold IS NULL) OR ((epss_threshold >= (0)::numeric) AND (epss_threshold <= (1)::numeric)))),
    CONSTRAINT chk_ci_gate_policies_mode CHECK (((mode)::text = ANY ((ARRAY['enforce'::character varying, 'warn'::character varying])::text[]))),
    CONSTRAINT chk_ci_gate_policies_scope CHECK (((((scope_type)::text = 'tenant'::text) AND (repository_asset_id IS NULL) AND (business_unit_id IS NULL)) OR (((scope_type)::text = 'repository'::text) AND (repository_asset_id IS NOT NULL) AND (business_unit_id IS NULL)) OR (((scope_type)::text = 'business_unit'::text) AND (business_unit_id IS NOT NULL) AND (repository_asset_id IS NULL)))),
    CONSTRAINT chk_ci_gate_policies_severity CHECK (((fail_on_severity)::text = ANY ((ARRAY['critical'::character varying, 'high'::character varying, 'medium'::character varying, 'low'::character varying, 'none'::character varying])::text[])))
);


