    retire_reason text,
    CONSTRAINT chk_ci_pipelines_provider CHECK (((provider)::text = ANY ((ARRAY['github'::character varying, 'gitlab'::character varying])::text[]))),
    CONSTRAINT chk_ci_pipelines_retire_reason CHECK (((retire_reason IS NULL) OR ((char_length(retire_reason) >= 10) AND (char_length(retire_reason) <= 2000)))),
    CONSTRAINT chk_ci_pipelines_tools CHECK ((jsonb_typeof(tools) = 'array'::text)),
    CONSTRAINT chk_ci_pipelines_verdicts CHECK ((((last_default_verdict IS NULL) OR ((last_default_verdict)::text = ANY ((ARRAY['pass'::character varying, 'fail'::character varying])::text[]))) AND ((last_pr_verdict IS NULL) OR ((last_pr_verdict)::text = ANY ((ARRAY['pass'::character varying, 'fail'::character varying])::text[])))))
);


