    CONSTRAINT chk_activity_type CHECK (((activity_type)::text = ANY ((ARRAY['created'::character varying, 'status_changed'::character varying, 'severity_changed'::character varying, 'resolved'::character varying, 'reopened'::character varying, 'assigned'::character varying, 'unassigned'::character varying, 'triage_updated'::character varying, 'false_positive_marked'::character varying, 'duplicate_marked'::character varying, 'duplicate_unmarked'::character varying, 'verified'::character varying, 'remediation_updated'::character varying, 'metadata_updated'::character varying, 'acceptance_expired'::character varying, 'comment_added'::character varying, 'comment_updated'::character varying, 'comment_deleted'::character varying, 'scan_detected'::character varying, 'auto_resolved'::character varying, 'auto_reopened'::character varying, 'linked'::character varying, 'unlinked'::character varying, 'sla_warning'::character varying, 'sla_breach'::character varying, 'sla_restarted'::character varying, 'ai_triage_requested'::character varying, 'ai_triage'::character varying, 'ai_triage_failed'::character varying, 'approval_requested'::character varying, 'approval_approved'::character varying, 'approval_rejected'::character varying, 'approval_canceled'::character varying, 'retest_requested'::character varying, 'retest_completed'::character varying])::text[]))),
    CONSTRAINT chk_actor_type CHECK (((actor_type)::text = ANY ((ARRAY['user'::character varying, 'system'::character varying, 'scanner'::character varying, 'integration'::character varying, 'ai'::character varying])::text[])))
);


