COMMENT ON COLUMN public.finding_data_flows.flow_index IS 'Order of this flow within the finding (0-based)';


--
-- Name: COLUMN finding_data_flows.importance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.finding_data_flows.importance IS 'SARIF threadFlowImportance: essential, important, unimportant';


--
-- Name: finding_definitions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.finding_definitions (
    finding_id uuid NOT NULL,
