    ord smallint NOT NULL,
    asserted_by character varying(20) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_finding_definitions_asserted_by CHECK (((asserted_by)::text = ANY ((ARRAY['report'::character varying, 'feed'::character varying, 'user'::character varying])::text[]))),
    CONSTRAINT chk_finding_definitions_ord CHECK (((ord >= 0) AND ((ord = 0) = ((role)::text = 'primary'::text)))),
    CONSTRAINT chk_finding_definitions_role CHECK (((role)::text = ANY ((ARRAY['primary'::character varying, 'detected_by'::character varying, 'additional'::character varying, 'alias'::character varying, 'weakness'::character varying])::text[]))),
    CONSTRAINT chk_finding_definitions_scope CHECK (((definition_scope = '00000000-0000-0000-0000-000000000000'::uuid) OR (definition_scope = tenant_id)))
);


--
-- Name: TABLE finding_definitions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.finding_definitions IS 'Links a finding to its definitions (RFC-044 §5.7): role primary at ord 0, then detected_by/additional/alias/weakness.';


--
-- Name: finding_fingerprints; Type: TABLE; Schema: public; Owner: -
--

