    CONSTRAINT chk_finding_fingerprints_version CHECK ((version >= 1))
);


--
-- Name: TABLE finding_fingerprints; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.finding_fingerprints IS 'Every fingerprint a finding has had, current and former, per tenant (RFC-043 §6). Ingest resolves an incoming key here.';


--
-- Name: finding_flow_locations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.finding_flow_locations (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    data_flow_id uuid NOT NULL,
    step_index integer NOT NULL,
    location_type character varying(20) DEFAULT 'intermediate'::character varying NOT NULL,
