    message text,
    nesting_level integer DEFAULT 0,
    importance character varying(20) DEFAULT 'essential'::character varying,
    CONSTRAINT chk_flow_location_type CHECK (((location_type)::text = ANY ((ARRAY['source'::character varying, 'intermediate'::character varying, 'sink'::character varying, 'sanitizer'::character varying])::text[]))),
    CONSTRAINT chk_location_importance CHECK (((importance)::text = ANY ((ARRAY['essential'::character varying, 'important'::character varying, 'unimportant'::character varying])::text[])))
);


--
-- Name: TABLE finding_flow_locations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.finding_flow_locations IS 'Individual steps in a data flow trace (source -> intermediate -> sink)';


