--

COMMENT ON COLUMN public.finding_flow_locations.location_type IS 'Role in flow: source (taint origin), intermediate (propagation), sink (vulnerable use), sanitizer (safe path)';


--
-- Name: COLUMN finding_flow_locations.label; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.finding_flow_locations.label IS 'Variable/expression name being tracked through the flow';


--
-- Name: COLUMN finding_flow_locations.nesting_level; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.finding_flow_locations.nesting_level IS 'SARIF nestingLevel for display indentation';


