);


--
-- Name: finding_imports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.finding_imports (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    actor_user_id uuid,
    format character varying(32) NOT NULL,
    filename_sha256 character(64) NOT NULL,
    assets_created integer DEFAULT 0 NOT NULL,
    assets_updated integer DEFAULT 0 NOT NULL,
    findings_created integer DEFAULT 0 NOT NULL,
    findings_updated integer DEFAULT 0 NOT NULL,
    components integer DEFAULT 0 NOT NULL,
    statements integer DEFAULT 0 NOT NULL,
    skipped integer DEFAULT 0 NOT NULL,
    vex_stored integer DEFAULT 0 NOT NULL,
    vex_closed integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_finding_imports_counts CHECK (((assets_created >= 0) AND (assets_updated >= 0) AND (findings_created >= 0) AND (findings_updated >= 0) AND (components >= 0) AND (statements >= 0) AND (skipped >= 0) AND (vex_stored >= 0) AND (vex_closed >= 0))),
    CONSTRAINT chk_finding_imports_sha CHECK ((filename_sha256 ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: TABLE finding_imports; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.finding_imports IS 'One row per file a person imported (POST /findings/import, never a preview): the producer of the findings whose scan_id and the assets whose import_id is this id.';


--
-- Name: COLUMN finding_imports.filename_sha256; Type: COMMENT; Schema: public; Owner: -
