--
-- Name: finding_retests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.finding_retests (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    finding_id uuid NOT NULL,
    asset_id uuid,
    trigger character varying(16) NOT NULL,
    requested_by uuid,
    status character varying(16) DEFAULT 'pending'::character varying NOT NULL,
    outcome character varying(16),
    reason text,
    prior_status character varying(30) NOT NULL,
    result_status character varying(30),
    template_id character varying(255) NOT NULL,
    target text NOT NULL,
    check_command_id uuid,
    reach_command_id uuid,
    deadline_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT chk_finding_retests_completed CHECK (((((status)::text = 'pending'::text) AND (outcome IS NULL) AND (completed_at IS NULL)) OR (((status)::text = 'completed'::text) AND (outcome IS NOT NULL) AND (completed_at IS NOT NULL)))),
    CONSTRAINT chk_finding_retests_outcome CHECK (((outcome IS NULL) OR ((outcome)::text = ANY ((ARRAY['fixed'::character varying, 'still_present'::character varying, 'unknown'::character varying])::text[])))),
    CONSTRAINT chk_finding_retests_status CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'completed'::character varying])::text[]))),
    CONSTRAINT chk_finding_retests_trigger CHECK (((trigger)::text = ANY ((ARRAY['manual'::character varying, 'auto'::character varying, 'proof_of_fix'::character varying])::text[])))
);


