);


--
-- Name: findings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.findings (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    tenant_id uuid NOT NULL,
    vulnerability_id uuid,
    asset_id uuid,
    branch_id uuid,
    component_id uuid,
    source character varying(20) NOT NULL,
    tool_name character varying(100) NOT NULL,
    tool_version character varying(50),
    rule_id character varying(255),
    rule_name character varying(500),
    sensor_id uuid,
    finding_type character varying(20) DEFAULT 'vulnerability'::character varying,
    file_path character varying(1000),
    start_line integer,
    end_line integer,
    start_column integer,
    end_column integer,
    snippet text,
    context_snippet text,
    context_start_line integer,
    title character varying(500),
    message text NOT NULL,
    description text,
    remediation jsonb,
    severity character varying(20) NOT NULL,
    cvss_score numeric(3,1),
    cvss_vector character varying(100),
    cve_id character varying(30),
    tags text[] DEFAULT '{}'::text[],
    status character varying(30) DEFAULT 'new'::character varying NOT NULL,
    resolution text,
    resolved_at timestamp with time zone,
    resolved_by uuid,
    acceptance_expires_at timestamp with time zone,
    sla_deadline timestamp with time zone,
    sla_status character varying(20) DEFAULT 'not_applicable'::character varying,
    scan_id character varying(100),
    fingerprint character varying(512) NOT NULL,
    assigned_to uuid,
    assigned_at timestamp with time zone,
    assigned_by uuid,
    verified_at timestamp with time zone,
    verified_by uuid,
    first_detected_at timestamp with time zone DEFAULT now(),
