    first_detected_commit character varying(64),
    last_seen_branch character varying(255),
    last_seen_commit character varying(64),
    cwe_ids text[] DEFAULT '{}'::text[],
    owasp_ids text[] DEFAULT '{}'::text[],
    related_issue_url character varying(1000),
    related_pr_url character varying(1000),
    duplicate_of uuid,
    duplicate_count integer DEFAULT 0 NOT NULL,
    comments_count integer DEFAULT 0 NOT NULL,
    exposure_vector character varying(50) DEFAULT 'unknown'::character varying,
    is_network_accessible boolean DEFAULT false,
    is_internet_accessible boolean DEFAULT false,
    attack_prerequisites text,
    remediation_type character varying(50),
    estimated_fix_time integer,
    fix_complexity character varying(20),
    remedy_available boolean DEFAULT true,
    data_exposure_risk character varying(20) DEFAULT 'none'::character varying,
    reputational_impact boolean DEFAULT false,
    compliance_impact text[],
    confidence integer,
    impact character varying(20),
    likelihood character varying(20),
    vulnerability_class text[],
    subcategory text[],
    baseline_state character varying(20),
    kind character varying(20),
    rank numeric(5,2),
    occurrence_count integer DEFAULT 1,
    correlation_id character varying(100),
    partial_fingerprints jsonb DEFAULT '{}'::jsonb,
    related_locations jsonb DEFAULT '[]'::jsonb,
    stacks jsonb DEFAULT '[]'::jsonb,
    attachments jsonb DEFAULT '[]'::jsonb,
    work_item_uris text[],
    hosted_viewer_uri character varying(2000),
    secret_type character varying(50),
    secret_service character varying(100),
    secret_valid boolean,
    secret_revoked boolean,
    secret_entropy numeric(5,2),
    secret_expires_at timestamp with time zone,
    compliance_framework character varying(50),
    compliance_control_id character varying(100),
    compliance_control_name character varying(500),
    compliance_result character varying(20),
    compliance_section character varying(100),
    web3_chain character varying(50),
    web3_chain_id bigint,
    web3_contract_address character varying(66),
    web3_swc_id character varying(20),
    web3_function_signature character varying(500),
    web3_tx_hash character varying(66),
    misconfig_policy_id character varying(100),
    misconfig_resource_type character varying(200),
    misconfig_resource_name character varying(500),
    misconfig_resource_path character varying(1000),
    misconfig_expected text,
    misconfig_actual text,
    asvs_section character varying(200),
    asvs_control_id character varying(50),
    asvs_control_url character varying(500),
    asvs_level integer,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tool_id uuid,
    pentest_campaign_id uuid,
    resolution_method character varying(30),
    created_by uuid,
    epss_score numeric(6,5),
    epss_percentile numeric(5,2),
    is_in_kev boolean DEFAULT false,
    kev_due_date date,
    priority_class character varying(2),
    priority_class_reason text,
    priority_class_override boolean DEFAULT false,
    priority_class_overridden_by uuid,
    priority_class_overridden_at timestamp with time zone,
    is_reachable boolean DEFAULT false,
    reachable_from_count integer DEFAULT 0,
    mitre_technique_id character varying(20),
    mitre_tactic character varying(50),
    is_regression boolean DEFAULT false,
    reopen_count integer DEFAULT 0,
    last_reopened_at timestamp with time zone,
    ingest_channel public.source_type,
    validation_outcome character varying(20),
    downgraded_at timestamp with time zone,
    type_details jsonb,
    last_seen_tool character varying(100),
    fingerprint_version smallint DEFAULT 1 NOT NULL,
    identity_key jsonb,
    network_port integer,
    network_transport character varying(8),
    network_service character varying(64),
    family character varying(255),
    exploit_available boolean DEFAULT false NOT NULL,
    vpr_score numeric(3,1),
    cvss_version character varying(8),
    cve_ids text[],
    patch_published_at timestamp with time zone,
    definition_id uuid,
    scanner_output text,
    scanner_output_at timestamp with time zone,
    cvss_v2_vector character varying(200),
    cvss_v3_vector character varying(200),
    template_digest text,
    template_path text,
    templates_version text,
    templates_digest text,
    template_seen_at timestamp with time zone,
    native_vuln_id text,
    native_scheme text,
    source_meta jsonb,
    scores jsonb,
    vulnerability_ids jsonb,
    source_extra jsonb,
    location_key text,
    vex_status text,
    vex_justification text,
    vex_statement text,
    vex_source text,
    vex_at timestamp with time zone,
    branch_only boolean DEFAULT false NOT NULL,
    CONSTRAINT check_attack_prerequisites_length CHECK (((attack_prerequisites IS NULL) OR (length(attack_prerequisites) <= 1024))),
    CONSTRAINT check_compliance_impact_size CHECK (((compliance_impact IS NULL) OR (array_length(compliance_impact, 1) <= 20))),
    CONSTRAINT chk_asvs_level CHECK (((asvs_level IS NULL) OR (asvs_level = ANY (ARRAY[1, 2, 3])))),
    CONSTRAINT chk_baseline_state CHECK (((baseline_state IS NULL) OR ((baseline_state)::text = ANY ((ARRAY['new'::character varying, 'unchanged'::character varying, 'updated'::character varying, 'absent'::character varying])::text[])))),
    CONSTRAINT chk_compliance_result CHECK (((compliance_result IS NULL) OR ((compliance_result)::text = ANY ((ARRAY['pass'::character varying, 'fail'::character varying, 'manual'::character varying, 'not_applicable'::character varying, 'error'::character varying, 'unknown'::character varying])::text[])))),
    CONSTRAINT chk_confidence CHECK (((confidence IS NULL) OR ((confidence >= 0) AND (confidence <= 100)))),
    CONSTRAINT chk_data_exposure_risk CHECK (((data_exposure_risk)::text = ANY ((ARRAY['none'::character varying, 'low'::character varying, 'medium'::character varying, 'high'::character varying, 'critical'::character varying])::text[]))),
    CONSTRAINT chk_exposure_vector CHECK (((exposure_vector)::text = ANY ((ARRAY['network'::character varying, 'local'::character varying, 'physical'::character varying, 'adjacent_net'::character varying, 'unknown'::character varying])::text[]))),
    CONSTRAINT chk_finding_type CHECK (((finding_type IS NULL) OR ((finding_type)::text = ANY ((ARRAY['vulnerability'::character varying, 'secret'::character varying, 'misconfiguration'::character varying, 'compliance'::character varying, 'web3'::character varying])::text[])))),
    CONSTRAINT chk_findings_cvss_score CHECK (((cvss_score IS NULL) OR ((cvss_score >= (0)::numeric) AND (cvss_score <= (10)::numeric)))),
    CONSTRAINT chk_findings_fingerprint_version CHECK ((fingerprint_version >= 1)),
    CONSTRAINT chk_findings_network_port CHECK (((network_port >= 1) AND (network_port <= 65535))),
    CONSTRAINT chk_findings_network_transport CHECK (((network_transport)::text = ANY ((ARRAY['tcp'::character varying, 'udp'::character varying, 'sctp'::character varying])::text[]))),
    CONSTRAINT chk_findings_severity CHECK (((severity)::text = ANY ((ARRAY['critical'::character varying, 'high'::character varying, 'medium'::character varying, 'low'::character varying, 'info'::character varying, 'none'::character varying])::text[]))),
    CONSTRAINT chk_findings_sla_status CHECK (((sla_status)::text = ANY ((ARRAY['on_track'::character varying, 'warning'::character varying, 'overdue'::character varying, 'exceeded'::character varying, 'not_applicable'::character varying])::text[]))),
    CONSTRAINT chk_findings_source CHECK (((source)::text = ANY ((ARRAY['sast'::character varying, 'dast'::character varying, 'sca'::character varying, 'secret'::character varying, 'iac'::character varying, 'container'::character varying, 'cspm'::character varying, 'easm'::character varying, 'va'::character varying, 'rasp'::character varying, 'waf'::character varying, 'siem'::character varying, 'manual'::character varying, 'pentest'::character varying, 'bug_bounty'::character varying, 'red_team'::character varying, 'external'::character varying, 'threat_intel'::character varying, 'vendor'::character varying, 'sarif'::character varying, 'sca_tool'::character varying, 'api'::character varying])::text[]))),
    CONSTRAINT chk_findings_status CHECK (((status)::text = ANY ((ARRAY['new'::character varying, 'open'::character varying, 'confirmed'::character varying, 'in_progress'::character varying, 'fix_applied'::character varying, 'validated_fixed'::character varying, 'not_observed'::character varying, 'resolved'::character varying, 'false_positive'::character varying, 'accepted'::character varying, 'duplicate'::character varying, 'draft'::character varying, 'in_review'::character varying, 'remediation'::character varying, 'retest'::character varying, 'verified'::character varying, 'accepted_risk'::character varying])::text[]))),
    CONSTRAINT chk_findings_type_details_shape CHECK (((type_details IS NULL) OR ((jsonb_typeof(type_details) = 'object'::text) AND ((type_details ->> 'v'::text) IS NOT NULL) AND (pg_column_size(type_details) <= 32768)))),
    CONSTRAINT chk_findings_validation_outcome CHECK (((validation_outcome IS NULL) OR ((validation_outcome)::text = ANY ((ARRAY['reproducible'::character varying, 'not_reproducible'::character varying])::text[])))),
    CONSTRAINT chk_fix_complexity CHECK (((fix_complexity IS NULL) OR ((fix_complexity)::text = ANY ((ARRAY['simple'::character varying, 'moderate'::character varying, 'complex'::character varying])::text[])))),
    CONSTRAINT chk_impact CHECK (((impact IS NULL) OR ((impact)::text = ANY ((ARRAY['critical'::character varying, 'high'::character varying, 'medium'::character varying, 'low'::character varying])::text[])))),
    CONSTRAINT chk_kind CHECK (((kind IS NULL) OR ((kind)::text = ANY ((ARRAY['not_applicable'::character varying, 'pass'::character varying, 'fail'::character varying, 'review'::character varying, 'open'::character varying, 'informational'::character varying])::text[])))),
    CONSTRAINT chk_likelihood CHECK (((likelihood IS NULL) OR ((likelihood)::text = ANY ((ARRAY['high'::character varying, 'medium'::character varying, 'low'::character varying])::text[])))),
    CONSTRAINT chk_priority_class CHECK (((priority_class IS NULL) OR ((priority_class)::text = ANY ((ARRAY['P0'::character varying, 'P1'::character varying, 'P2'::character varying, 'P3'::character varying])::text[])))),
    CONSTRAINT chk_rank CHECK (((rank IS NULL) OR ((rank >= (0)::numeric) AND (rank <= (100)::numeric)))),
    CONSTRAINT chk_remediation_type CHECK (((remediation_type IS NULL) OR ((remediation_type)::text = ANY ((ARRAY['patch'::character varying, 'upgrade'::character varying, 'workaround'::character varying, 'config_change'::character varying, 'mitigate'::character varying, 'accept_risk'::character varying])::text[]))))
);


--
-- Name: TABLE findings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.findings IS 'Security findings (vulnerability instances) with CTEM, SARIF, and multi-type support';


--
-- Name: COLUMN findings.finding_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.finding_type IS 'Type discriminator: vulnerability, secret, misconfiguration, compliance, web3';


--
-- Name: COLUMN findings.remediation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.remediation IS 'Consolidated remediation info: recommendation, fix_code, fix_regex, steps, references';


--
-- Name: COLUMN findings.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.status IS 'Unified workflow: new → confirmed → in_progress → resolved (or false_positive, accepted, duplicate)';


--
-- Name: COLUMN findings.acceptance_expires_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.acceptance_expires_at IS 'When risk acceptance expires (requires re-review)';


--
-- Name: COLUMN findings.exposure_vector; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.exposure_vector IS 'CTEM: How the vulnerability can be reached (network, local, physical, adjacent_net)';


--
-- Name: COLUMN findings.is_internet_accessible; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.is_internet_accessible IS 'CTEM: True if finding is on internet-facing asset';


--
-- Name: COLUMN findings.remediation_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.remediation_type IS 'CTEM: Recommended fix type (patch, upgrade, workaround, etc.)';


--
-- Name: COLUMN findings.confidence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.confidence IS 'SARIF: Confidence score 0-100 (probability of true positive)';


--
-- Name: COLUMN findings.baseline_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.baseline_state IS 'SARIF: Change state (new, unchanged, updated, absent)';


--
-- Name: COLUMN findings.correlation_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.correlation_id IS 'SARIF: Groups logically identical results across scans';


--
-- Name: COLUMN findings.ingest_channel; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.ingest_channel IS 'Which channel reported this finding: integration | collector | scanner | manual. Distinct from findings.source, which records the technique. NULL means unrecorded (written before migration 000197).';


--
-- Name: COLUMN findings.type_details; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.type_details IS 'Typed, versioned type-specific facts without a column ({"v":1,"secret"|"misconfig"|"compliance"|"web3":{...}}). Never holds a secret value.';


--
-- Name: COLUMN findings.last_seen_tool; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.last_seen_tool IS 'Tool of the last sighting (written with scan_id). Auto-resolve closes a finding only for this tool; NULL falls back to tool_name.';


--
-- Name: COLUMN findings.fingerprint_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.fingerprint_version IS 'Version of the identity recipe that produced fingerprint (RFC-043 §6).';


--
-- Name: COLUMN findings.identity_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.identity_key IS 'Canonical identity tuple the fingerprint was hashed from, so the key can be recomputed without the original report (RFC-043 §4.1.3).';


--
-- Name: COLUMN findings.network_port; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.network_port IS 'Port the finding was observed on (CTIS Finding.Network.Port); NULL = not port-specific or unknown. Not a fingerprint input.';


--
-- Name: COLUMN findings.network_transport; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.network_transport IS 'Transport of network_port: tcp, udp or sctp.';


--
-- Name: COLUMN findings.network_service; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.network_service IS 'Service on network_port as the scanner named it (https, ssh, ...).';


--
-- Name: COLUMN findings.family; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.family IS 'Rule family or category from the scanner (CTIS Finding.Category): Nessus/Tenable.sc plugin family, Semgrep/Checkov category. Not a fingerprint input.';


--
-- Name: COLUMN findings.exploit_available; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.exploit_available IS 'The scanner reported a public exploit (this tenant''s observation; the CVE catalog has its own flag).';


--
-- Name: COLUMN findings.vpr_score; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.vpr_score IS 'Tenable Vulnerability Priority Rating 0.1-10. Display only: not a prioritization input (research 17 A3).';


--
-- Name: COLUMN findings.cvss_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.cvss_version IS 'Version of cvss_score: 2.0, 3.0, 3.1, 3.x or 4.0.';


--
-- Name: COLUMN findings.cve_ids; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.cve_ids IS 'Every CVE the scanner named on this finding, primary first (cve_id is the primary). Multi-CVE network plugins are split into one finding per CVE (RFC-043 D3).';


--
-- Name: COLUMN findings.patch_published_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.patch_published_at IS 'When the vendor published the fix (Nessus patch_publication_date, Tenable.sc patchPubDate).';


--
-- Name: COLUMN findings.definition_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.definition_id IS 'Primary definition (RFC-044 §5.7), denormalized from finding_definitions ord 0.';


--
-- Name: COLUMN findings.scanner_output; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.scanner_output IS 'Scanner output for this finding (plugin output, evidence text) from its latest sighting. Untrusted text, at most 64 KiB; detail view only; cleared 365 days after close.';


--
-- Name: COLUMN findings.scanner_output_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.scanner_output_at IS 'When scanner_output was last written (the sighting it came from).';


--
-- Name: COLUMN findings.cvss_v2_vector; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.cvss_v2_vector IS 'CVSS v2 vector reported by the scanner.';


--
-- Name: COLUMN findings.cvss_v3_vector; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.cvss_v3_vector IS 'CVSS v3.x vector reported by the scanner.';


--
-- Name: COLUMN findings.template_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.template_digest IS 'sha256 of the template file that matched at the last sighting (sensor properties.template_digest); research/18 O6.';


--
-- Name: COLUMN findings.template_path; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.template_path IS 'Path of that template inside the release (properties.template_path).';


--
-- Name: COLUMN findings.templates_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.templates_version IS 'Template release the last sighting ran with (tool.properties.content).';


--
-- Name: COLUMN findings.templates_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.templates_digest IS 'Archive digest of that release.';


--
-- Name: COLUMN findings.template_seen_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.template_seen_at IS 'When the template provenance was last recorded.';


--
-- Name: COLUMN findings.native_vuln_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.native_vuln_id IS 'Source id of the check (plugin ID, QID, rule id); CTIS native.vuln_id. Untrusted.';


--
-- Name: COLUMN findings.native_scheme; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.native_scheme IS 'Vocabulary of the native values (CTIS native.scheme).';


--
-- Name: COLUMN findings.source_meta; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.source_meta IS 'Native identity, source lifecycle and solution metadata of the latest sighting (CTIS 1.4). Untrusted; detail view only.';


--
-- Name: COLUMN findings.scores; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.scores IS 'Every score of the latest sighting with system, version, vector, value, source and date (CTIS scores + legacy cvss/epss/vpr).';


--
-- Name: COLUMN findings.vulnerability_ids; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.vulnerability_ids IS 'Typed vulnerability ids of the latest sighting (cve, ghsa, osv, vendor).';


--
-- Name: COLUMN findings.source_extra; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.source_extra IS 'Unmapped source fields of the latest sighting, strings, bounded. Untrusted; detail view only.';


--
-- Name: COLUMN findings.location_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.location_key IS 'Normalized location on the asset (ctis.LocationKey), derived by the server.';


--
-- Name: COLUMN findings.vex_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.vex_status IS 'Latest VEX status reported for the finding.';


--
-- Name: COLUMN findings.vex_justification; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.vex_justification IS 'VEX not_affected justification (CSAF / OpenVEX).';


--
-- Name: COLUMN findings.vex_statement; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.vex_statement IS 'VEX impact or action statement. Untrusted plain text.';


--
-- Name: COLUMN findings.vex_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.vex_source IS 'Who made the VEX statement (document id or URL, vendor, team), as reported.';


--
-- Name: COLUMN findings.vex_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.vex_at IS 'When the VEX statement was made (or recorded, when the source gave no date).';


--
-- Name: COLUMN findings.branch_only; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.findings.branch_only IS 'Seen only on branches that do not count as exposure (branch_counts_as_exposure). Excluded from exposure views; cleared when a counting branch sees the finding.';


