--
-- Name: ingest_reports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ingest_reports (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    sensor_id uuid NOT NULL,
    report_id uuid NOT NULL,
    command_id uuid,
    scan_zone_id uuid,
    state text DEFAULT 'receiving'::text NOT NULL,
    protocol smallint DEFAULT 2 NOT NULL,
    media_type text NOT NULL,
    sensor_type text DEFAULT ''::text NOT NULL,
    user_agent text DEFAULT ''::text NOT NULL,
    header_digest text NOT NULL,
    header jsonb DEFAULT '{}'::jsonb NOT NULL,
    tool_name text DEFAULT ''::text NOT NULL,
    implicit_commit boolean DEFAULT false NOT NULL,
    segment_count integer,
    segments_received integer DEFAULT 0 NOT NULL,
    committed_at timestamp with time zone,
    segment_outcomes jsonb DEFAULT '{}'::jsonb NOT NULL,
    touched_asset_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    auto_resolved integer DEFAULT 0 NOT NULL,
    auto_resolve text,
    expires_at timestamp with time zone NOT NULL,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    assets_received integer DEFAULT 0 NOT NULL,
    findings_received integer DEFAULT 0 NOT NULL,
    CONSTRAINT ingest_reports_auto_resolve_check CHECK (((auto_resolve IS NULL) OR (auto_resolve = ANY (ARRAY['applied'::text, 'held'::text, 'skipped'::text])))),
    CONSTRAINT ingest_reports_item_totals_check CHECK (((assets_received >= 0) AND (findings_received >= 0))),
    CONSTRAINT ingest_reports_protocol_check CHECK ((protocol = 2)),
    CONSTRAINT ingest_reports_segment_count_check CHECK (((segment_count IS NULL) OR ((segment_count >= 1) AND (segment_count <= 256)))),
    CONSTRAINT ingest_reports_segments_check CHECK ((segments_received >= 0)),
    CONSTRAINT ingest_reports_state_check CHECK ((state = ANY (ARRAY['receiving'::text, 'queued'::text, 'processing'::text, 'completed'::text, 'failed'::text, 'expired'::text])))
);


