    asset_group_ids uuid[] DEFAULT '{}'::uuid[],
    targets text[] DEFAULT '{}'::text[],
    scan_type character varying(20) NOT NULL,
    pipeline_id uuid,
    scanner_name character varying(100),
    scanner_config jsonb DEFAULT '{}'::jsonb,
    targets_per_job integer DEFAULT 1,
    schedule_type character varying(20) DEFAULT 'manual'::character varying NOT NULL,
    schedule_cron character varying(100),
    schedule_day integer,
    schedule_time time without time zone,
    schedule_timezone character varying(50) DEFAULT 'UTC'::character varying,
    next_run_at timestamp with time zone,
    tags text[] DEFAULT '{}'::text[],
    run_on_tenant_runner boolean DEFAULT false,
    status character varying(20) DEFAULT 'active'::character varying NOT NULL,
    last_run_id uuid,
    last_run_at timestamp with time zone,
    last_run_status character varying(20),
    total_runs integer DEFAULT 0,
    successful_runs integer DEFAULT 0,
    failed_runs integer DEFAULT 0,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    sensor_preference character varying(20) DEFAULT 'auto'::character varying NOT NULL,
    profile_id uuid,
    timeout_seconds integer DEFAULT 3600 NOT NULL,
    max_retries integer DEFAULT 0 NOT NULL,
    retry_backoff_seconds integer DEFAULT 60 NOT NULL,
    scan_zone_id uuid,
    ad_hoc boolean DEFAULT false NOT NULL,
    partial_runs integer DEFAULT 0 NOT NULL,
    schedule_rrule text,
    CONSTRAINT chk_scan_has_targets CHECK (((asset_group_id IS NOT NULL) OR ((asset_group_ids IS NOT NULL) AND (array_length(asset_group_ids, 1) > 0)) OR ((targets IS NOT NULL) AND (array_length(targets, 1) > 0)))),
    CONSTRAINT chk_scans_max_retries CHECK (((max_retries >= 0) AND (max_retries <= 10))),
    CONSTRAINT chk_scans_partial_runs CHECK ((partial_runs >= 0)),
    CONSTRAINT chk_scans_retry_backoff CHECK (((retry_backoff_seconds >= 10) AND (retry_backoff_seconds <= 86400))),
    CONSTRAINT chk_scans_scan_type CHECK (((scan_type)::text = ANY ((ARRAY['workflow'::character varying, 'single'::character varying])::text[]))),
    CONSTRAINT chk_scans_schedule_rrule CHECK (((schedule_rrule IS NULL) OR ((length(schedule_rrule) >= 1) AND (length(schedule_rrule) <= 500)))),
    CONSTRAINT chk_scans_schedule_type CHECK (((schedule_type)::text = ANY ((ARRAY['manual'::character varying, 'daily'::character varying, 'weekly'::character varying, 'monthly'::character varying, 'crontab'::character varying, 'rrule'::character varying])::text[]))),
    CONSTRAINT chk_scans_sensor_preference CHECK (((sensor_preference)::text = ANY ((ARRAY['auto'::character varying, 'tenant'::character varying, 'platform'::character varying])::text[]))),
    CONSTRAINT chk_scans_status CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'paused'::character varying, 'disabled'::character varying])::text[]))),
    CONSTRAINT chk_scans_timeout_seconds CHECK (((timeout_seconds > 0) AND (timeout_seconds <= 86400))),
    CONSTRAINT scans_chk_single_has_scanner CHECK ((((scan_type)::text <> 'single'::text) OR (scanner_name IS NOT NULL))),
    CONSTRAINT scans_chk_workflow_has_pipeline CHECK ((((scan_type)::text <> 'workflow'::text) OR (pipeline_id IS NOT NULL)))
);


