    CONSTRAINT chk_sensor_pairings_bound CHECK ((((status)::text <> ALL ((ARRAY['approved'::character varying, 'completed'::character varying])::text[])) OR ((tenant_id IS NOT NULL) AND (sensor_id IS NOT NULL)))),
    CONSTRAINT chk_sensor_pairings_key CHECK ((((status)::text = 'expecting'::text) = (public_key IS NULL))),
