    CONSTRAINT chk_sensor_pairings_public_key CHECK (((public_key IS NULL) OR (octet_length(public_key) = 32))),
    CONSTRAINT chk_sensor_pairings_status CHECK (((status)::text = ANY ((ARRAY['expecting'::character varying, 'pending'::character varying, 'approved'::character varying, 'completed'::character varying, 'denied'::character varying, 'expired'::character varying])::text[])))
);


