    capabilities text[] DEFAULT '{}'::text[],
    tools text[] DEFAULT '{}'::text[],
    execution_mode character varying(20) DEFAULT 'standalone'::character varying,
    status character varying(50) DEFAULT 'pending'::character varying,
    status_message character varying(255),
    health character varying(20) DEFAULT 'unknown'::character varying,
    api_key_hash character varying(64) NOT NULL,
    api_key_prefix character varying(12) NOT NULL,
    version character varying(50),
    hostname character varying(255),
    ip_address inet,
    labels jsonb DEFAULT '{}'::jsonb,
    config jsonb DEFAULT '{}'::jsonb,
    metadata jsonb DEFAULT '{}'::jsonb,
    last_seen_at timestamp with time zone,
    last_error_at timestamp with time zone,
    last_offline_at timestamp with time zone,
    total_findings bigint DEFAULT 0,
    total_scans bigint DEFAULT 0,
    error_count bigint DEFAULT 0,
    max_concurrent_jobs integer DEFAULT 5,
    current_jobs integer DEFAULT 0,
    cpu_percent numeric(5,2) DEFAULT 0,
    memory_percent numeric(5,2) DEFAULT 0,
    disk_read_mbps numeric(10,2),
    disk_write_mbps numeric(10,2),
    network_rx_mbps numeric(10,2),
    network_tx_mbps numeric(10,2),
    load_score numeric(10,4),
    metrics_updated_at timestamp with time zone,
    last_error text,
    region character varying(64) DEFAULT ''::character varying,
    is_platform_sensor boolean DEFAULT false NOT NULL,
    tier character varying(20),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    key_expires_at timestamp with time zone,
    outbox_stats jsonb,
    outbox_reported_at timestamp with time zone,
    protocol_version smallint,
    protocol_client character varying(256),
    protocol_seen_at timestamp with time zone,
    process_started_at timestamp with time zone,
    reported_tools jsonb,
    reported_tool_names text[],
    reported_capabilities text[],
    reported_max_jobs integer,
    reported_os character varying(32),
    reported_arch character varying(32),
    reported_at timestamp with time zone,
    effective_tools text[] GENERATED ALWAYS AS (public.sensor_effective_list(tools, reported_tool_names)) STORED,
    effective_capabilities text[] GENERATED ALWAYS AS (public.sensor_effective_list(capabilities, reported_capabilities)) STORED,
    effective_max_jobs integer GENERATED ALWAYS AS (public.sensor_effective_max_jobs(max_concurrent_jobs, reported_max_jobs, reported_capacity)) STORED,
    reported_resources jsonb,
    reported_capacity jsonb,
    reported_queue jsonb,
    load_reported_at timestamp with time zone,
    sdk_name character varying(64),
    sdk_version character varying(64),
    sensor_product character varying(64),
    sensor_commit character varying(40),
    sensor_build_time timestamp with time zone,
    api_key_last_used_at timestamp with time zone,
    api_key_last_used_ip inet,
    instance_id character varying(64),
    instance_state jsonb DEFAULT '{}'::jsonb NOT NULL,
    identity_cloned_at timestamp with time zone,
    manifest_digest character varying(71),
    manifest_at timestamp with time zone,
    manifest_source character varying(16),
    heartbeat_interval_seconds integer,
    heartbeat_due_at timestamp with time zone,
    reported_control jsonb,
    control_reported_at timestamp with time zone,
    key_pepper_id text,
    reported_local_policy jsonb,
    local_policy_reported_at timestamp with time zone,
    config_report_digest text,
    config_health text,
    config_heartbeat_digest text,
    auth_kind character varying(16) DEFAULT 'bearer'::character varying NOT NULL,
    trust_level character varying(16) DEFAULT 'new'::character varying NOT NULL,
    CONSTRAINT chk_sensors_auth_kind CHECK (((auth_kind)::text = ANY ((ARRAY['bearer'::character varying, 'key_bound'::character varying])::text[]))),
    CONSTRAINT chk_sensors_config_health CHECK (((config_health IS NULL) OR (config_health = ANY (ARRAY['ok'::text, 'attention'::text, 'impaired'::text, 'blocked'::text])))),
    CONSTRAINT chk_sensors_execution_mode CHECK (((execution_mode)::text = ANY ((ARRAY['standalone'::character varying, 'daemon'::character varying])::text[]))),
    CONSTRAINT chk_sensors_health CHECK (((health)::text = ANY ((ARRAY['unknown'::character varying, 'online'::character varying, 'late'::character varying, 'stale'::character varying, 'offline'::character varying, 'error'::character varying])::text[]))),
    CONSTRAINT chk_sensors_heartbeat_interval CHECK (((heartbeat_interval_seconds IS NULL) OR ((heartbeat_interval_seconds >= 1) AND (heartbeat_interval_seconds <= 300)))),
    CONSTRAINT chk_sensors_reported_local_policy CHECK (((reported_local_policy IS NULL) OR (jsonb_typeof(reported_local_policy) = 'object'::text))),
    CONSTRAINT chk_sensors_status CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'disabled'::character varying, 'revoked'::character varying])::text[]))),
    CONSTRAINT chk_sensors_tier CHECK (((tier IS NULL) OR ((tier)::text = ANY ((ARRAY['shared'::character varying, 'dedicated'::character varying, 'premium'::character varying])::text[])))),
    CONSTRAINT chk_sensors_trust_level CHECK (((trust_level)::text = ANY ((ARRAY['new'::character varying, 'trusted'::character varying])::text[]))),
    CONSTRAINT chk_sensors_type CHECK (((type)::text = ANY ((ARRAY['worker'::character varying, 'agent'::character varying, 'scanner'::character varying, 'collector'::character varying, 'platform'::character varying, 'sensor'::character varying])::text[]))),
    CONSTRAINT sensors_instance_state_object CHECK ((jsonb_typeof(instance_state) = 'object'::text))
);


--
-- Name: TABLE sensors; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sensors IS 'Sensor registry: scanners, agents and collectors that authenticate to the platform with their own key (RFC-023)';


--
-- Name: COLUMN sensors.health; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.health IS 'Automatic heartbeat state: unknown, online, late (past its deadline, still dispatchable), stale (not dispatchable), offline, error.';


--
-- Name: COLUMN sensors.outbox_stats; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.outbox_stats IS 'Latest outbox snapshot from the heartbeat: pending_count, pending_bytes, oldest_age_seconds, dead_letter_count, evicted_count. NULL = never reported.';


--
-- Name: COLUMN sensors.outbox_reported_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.outbox_reported_at IS 'When outbox_stats was last reported.';


--
-- Name: COLUMN sensors.protocol_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.protocol_version IS 'Sensor protocol of the last heartbeat: 1 (deprecated) or 2 (RFC-029). NULL before the first heartbeat that recorded it.';


--
-- Name: COLUMN sensors.protocol_client; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.protocol_client IS 'User-Agent of the last heartbeat (printable ASCII, at most 256 bytes). Untrusted, display only.';


--
-- Name: COLUMN sensors.protocol_seen_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.protocol_seen_at IS 'When protocol_version and protocol_client were last written.';


--
-- Name: COLUMN sensors.process_started_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.process_started_at IS 'Start time of the sensor process (heartbeat time minus the reported uptime_seconds). NULL until a heartbeat reports an uptime.';


--
-- Name: COLUMN sensors.reported_tools; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.reported_tools IS 'Tool inventory the sensor last reported: [{name, version, installed}], names in the tool catalog only. Untrusted, sanitized at ingest. NULL: never reported.';


--
-- Name: COLUMN sensors.reported_tool_names; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.reported_tool_names IS 'Names of the installed tools in reported_tools (the dispatch input). NULL: never reported.';


--
-- Name: COLUMN sensors.reported_capabilities; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.reported_capabilities IS 'Capabilities the sensor last reported (known names only). NULL: never reported.';


--
-- Name: COLUMN sensors.reported_max_jobs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.reported_max_jobs IS 'The sensor operator''s ceiling on concurrent jobs (SENSOR_MAX_JOBS), 1..100. NULL: none reported. What the sensor can run now is reported_capacity.slots_total.';


--
-- Name: COLUMN sensors.reported_os; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.reported_os IS 'Operating system the sensor reported (display only).';


--
-- Name: COLUMN sensors.reported_arch; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.reported_arch IS 'Architecture the sensor reported (display only).';


--
-- Name: COLUMN sensors.reported_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.reported_at IS 'When the capability report was last written.';


--
-- Name: COLUMN sensors.effective_tools; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.effective_tools IS 'Tools dispatch uses: reported installed tools narrowed by tools (generated).';


--
-- Name: COLUMN sensors.effective_capabilities; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.effective_capabilities IS 'Capabilities dispatch and the command poll use: reported narrowed by capabilities (generated).';


--
-- Name: COLUMN sensors.effective_max_jobs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.effective_max_jobs IS 'Capacity dispatch uses: the smallest of max_concurrent_jobs (admin), reported_max_jobs (operator ceiling) and reported_capacity.slots_total (slots now) that is set (generated).';


--
-- Name: COLUMN sensors.reported_resources; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.reported_resources IS 'Resources the sensor last reported: {cpu_cores, cpu_used_pct, mem_total_bytes, mem_available_bytes, load1, disk_free_bytes}. Untrusted, clamped at ingest. Display and selection input only.';


--
-- Name: COLUMN sensors.reported_capacity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.reported_capacity IS 'Job capacity the sensor last reported: {slots_total, slots_free, active_jobs, per_tool: {tool: {est_cpu_s, est_mem_bytes, throughput_targets_per_min}}}. Untrusted, clamped; can only lower dispatch capacity.';


--
-- Name: COLUMN sensors.reported_queue; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.reported_queue IS 'The sensor''s local work queue as last reported: {claimed, running, queued_local, oldest_age_seconds}. Display only.';


--
-- Name: COLUMN sensors.load_reported_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.load_reported_at IS 'When a load report (resources, capacity or queue) was last written; a report older than 3 minutes is not used for dispatch.';


--
-- Name: COLUMN sensors.sdk_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.sdk_name IS 'SDK the sensor is built with (e.g. openctem-sdk-go), from the heartbeat or its User-Agent. Display data.';


--
-- Name: COLUMN sensors.sdk_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.sdk_version IS 'SDK version (normalized, e.g. v0.9.0). Compared with SENSOR_SDK_MIN_VERSION / SENSOR_SDK_LATEST_VERSION.';


--
-- Name: COLUMN sensors.sensor_product; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.sensor_product IS 'Sensor product name (e.g. openctemio-sensor). The sensor version is sensors.version.';


--
-- Name: COLUMN sensors.sensor_commit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.sensor_commit IS 'Source commit the sensor binary was built from, when reported.';


--
-- Name: COLUMN sensors.sensor_build_time; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.sensor_build_time IS 'Build time of the sensor binary, when reported.';


--
-- Name: COLUMN sensors.api_key_last_used_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.api_key_last_used_at IS 'Last authenticated request with any of the sensor''s keys (RFC-032 Phase 0).';


--
-- Name: COLUMN sensors.api_key_last_used_ip; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.api_key_last_used_ip IS 'Client address of that request, resolved with the trusted-proxy rule; never a header the sensor sets.';


--
-- Name: COLUMN sensors.instance_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.instance_id IS 'Process instance of the last heartbeat that changed it: the SDK-generated instance id, or host:<hash> derived from the hostname for older SDKs.';


--
-- Name: COLUMN sensors.instance_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.instance_state IS 'Clone-detection memory: recently seen instances and the times a replaced instance came back (pkg/domain/sensor/identity.go).';


--
-- Name: COLUMN sensors.identity_cloned_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.identity_cloned_at IS 'When two live instances were seen using the same key; NULL = not flagged. Cleared when the key is regenerated.';


--
-- Name: COLUMN sensors.manifest_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.manifest_digest IS 'Digest of the current manifest (sensor_manifests.digest); the sensor echoes it on its heartbeat (RFC-033). NULL: none yet.';


--
-- Name: COLUMN sensors.manifest_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.manifest_at IS 'When the current manifest became current.';


--
-- Name: COLUMN sensors.manifest_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.manifest_source IS 'sensor (PUT /api/v2/sensor/manifest) or heartbeat (derived by the platform).';


--
-- Name: COLUMN sensors.heartbeat_interval_seconds; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.heartbeat_interval_seconds IS 'Heartbeat interval the sensor follows, stored at its last heartbeat (reported control.interval_s or the advised interval, 1..300 s). NULL: not heartbeated since migration 000261 (60 s applies).';


--
-- Name: COLUMN sensors.heartbeat_due_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.heartbeat_due_at IS 'When the next heartbeat is due: last heartbeat + heartbeat_interval_seconds. The health controller''s ladder is relative to it (RFC-035 §5.6).';


--
-- Name: COLUMN sensors.reported_control; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.reported_control IS 'Control-channel report of the last heartbeat that carried one (interval_s, gap_s, lag_ms, build_ms, rtt_ms, failures), clamped. NULL: never reported.';


--
-- Name: COLUMN sensors.control_reported_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.control_reported_at IS 'When reported_control was stored.';


--
-- Name: COLUMN sensors.reported_local_policy; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.reported_local_policy IS 'The sensor-local policy report of the last heartbeat or manifest that carried one (RFC-040 §5.7): state, source, digest, summary, kill_switch, warnings. NULL = never reported.';


--
-- Name: COLUMN sensors.local_policy_reported_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.local_policy_reported_at IS 'When reported_local_policy was last written.';


--
-- Name: COLUMN sensors.config_report_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.config_report_digest IS 'Digest of the stored config report (sensor_config_reports.digest). NULL: the sensor never sent one.';


--
-- Name: COLUMN sensors.config_health; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.config_health IS 'The platform health rollup of the stored config report: ok, attention, impaired or blocked. NULL: no report.';


--
-- Name: COLUMN sensors.config_heartbeat_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.config_heartbeat_digest IS 'The config report digest the latest heartbeat echoed. NULL: it echoed none.';


--
-- Name: COLUMN sensors.auth_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.auth_kind IS 'bearer (octs_/rda_ key) or key_bound (Ed25519 key, signed requests; RFC-052).';


--
-- Name: COLUMN sensors.trust_level; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sensors.trust_level IS 'new: passive work only, no credentials, no results without a job, until an administrator promotes it; trusted: the full grant applies (RFC-052 §5).';


--
-- Name: sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sessions (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    user_id uuid NOT NULL,
    access_token_hash character varying(64) NOT NULL,
    ip_address character varying(45),
    user_agent text,
    device_fingerprint character varying(64),
    expires_at timestamp with time zone NOT NULL,
    last_activity_at timestamp with time zone DEFAULT now() NOT NULL,
    status character varying(20) DEFAULT 'active'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    auth_method character varying(20) DEFAULT 'password'::character varying NOT NULL,
    idp_issuer text,
    idp_sid text,
    idp_sub text,
    idp_tenant_id uuid,
    step_up_at timestamp with time zone,
    CONSTRAINT chk_sessions_auth_method CHECK (((auth_method)::text = ANY ((ARRAY['password'::character varying, 'sso'::character varying, 'saml'::character varying])::text[]))),
    CONSTRAINT chk_sessions_status CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'expired'::character varying, 'revoked'::character varying])::text[])))
);


--
-- Name: TABLE sessions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sessions IS 'User sessions for local authentication';


--
-- Name: COLUMN sessions.auth_method; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sessions.auth_method IS 'How the session was authenticated: password (local login), sso (federated OIDC/OAuth), or saml. Used by per-tenant SSO enforcement.';


--
-- Name: COLUMN sessions.idp_issuer; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sessions.idp_issuer IS 'Verified OIDC id_token iss for federated sessions; scopes back-channel logout per-provider. NULL for local/SAML sessions.';


--
-- Name: COLUMN sessions.idp_sid; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sessions.idp_sid IS 'OIDC id_token sid (IdP session id) for OIDC Back-Channel Logout 1.0. NULL when absent.';


--
-- Name: COLUMN sessions.idp_sub; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sessions.idp_sub IS 'OIDC id_token sub (IdP subject) for sub-only back-channel logout. NULL when absent.';


--
-- Name: COLUMN sessions.idp_tenant_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sessions.idp_tenant_id IS 'Organization whose SAML/OIDC identity provider issued this federated session. Only that organization treats the session as an SSO sign-in (SSO enforcement, 2FA requirement). NULL for password, social OAuth and pre-000269 sessions.';


--
-- Name: COLUMN sessions.step_up_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sessions.step_up_at IS 'Last successful step-up re-authentication in this session (NULL = none since sign-in)';


--
-- Name: settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.settings (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    tenant_id uuid,
    key character varying(255) NOT NULL,
    category character varying(100) DEFAULT 'general'::character varying NOT NULL,
    value_type character varying(20) DEFAULT 'string'::character varying NOT NULL,
    value_json jsonb,
    description text,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_setting_value_type CHECK (((value_type)::text = ANY ((ARRAY['string'::character varying, 'int'::character varying, 'float'::character varying, 'bool'::character varying, 'json'::character varying])::text[])))
);


--
-- Name: TABLE settings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.settings IS 'System and tenant settings with typed values';


--
-- Name: COLUMN settings.tenant_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.settings.tenant_id IS 'NULL = system-wide setting';


--
-- Name: COLUMN settings.value_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.settings.value_type IS 'Value type: string, int, float, bool, json';


--
-- Name: sla_policies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sla_policies (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    tenant_id uuid NOT NULL,
    asset_id uuid,
    name character varying(255) NOT NULL,
    description text,
    is_default boolean DEFAULT false NOT NULL,
    critical_days integer DEFAULT 1 NOT NULL,
    high_days integer DEFAULT 7 NOT NULL,
    medium_days integer DEFAULT 30 NOT NULL,
    low_days integer DEFAULT 90 NOT NULL,
    info_days integer DEFAULT 365 NOT NULL,
    warning_threshold_percent integer DEFAULT 75 NOT NULL,
    escalation_enabled boolean DEFAULT true NOT NULL,
    escalation_config jsonb DEFAULT '{}'::jsonb,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    p0_days integer,
    p1_days integer,
    p2_days integer,
    p3_days integer,
    CONSTRAINT chk_sla_policies_priority_days CHECK ((((p0_days IS NULL) OR ((p0_days >= 1) AND (p0_days <= 365))) AND ((p1_days IS NULL) OR ((p1_days >= 1) AND (p1_days <= 365))) AND ((p2_days IS NULL) OR ((p2_days >= 1) AND (p2_days <= 365))) AND ((p3_days IS NULL) OR ((p3_days >= 1) AND (p3_days <= 365)))))
);


--
-- Name: TABLE sla_policies; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sla_policies IS 'SLA policies defining remediation deadlines by severity';


--
-- Name: COLUMN sla_policies.asset_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sla_policies.asset_id IS 'NULL = tenant-wide default policy, set = asset-specific override';


--
-- Name: COLUMN sla_policies.warning_threshold_percent; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sla_policies.warning_threshold_percent IS 'Percentage of deadline elapsed before warning';


--
-- Name: COLUMN sla_policies.escalation_enabled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sla_policies.escalation_enabled IS 'Send approaching/breached deadline notifications for findings governed by this policy';


--
-- Name: COLUMN sla_policies.p0_days; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sla_policies.p0_days IS 'Remediation window (days) for priority class P0; NULL = platform default';


--
-- Name: COLUMN sla_policies.p1_days; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sla_policies.p1_days IS 'Remediation window (days) for priority class P1; NULL = platform default';


--
-- Name: COLUMN sla_policies.p2_days; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sla_policies.p2_days IS 'Remediation window (days) for priority class P2; NULL = platform default';


--
-- Name: COLUMN sla_policies.p3_days; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sla_policies.p3_days IS 'Remediation window (days) for priority class P3; NULL = platform default';


--
-- Name: sso_pending_changes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sso_pending_changes (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    kind character varying(32) NOT NULL,
    target_id uuid,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    secret_encrypted text,
    status character varying(16) DEFAULT 'pending'::character varying NOT NULL,
    requested_by_admin uuid,
    requested_by_email character varying(320) DEFAULT ''::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    decided_at timestamp with time zone,
    decided_by uuid,
    CONSTRAINT chk_sso_pending_changes_kind CHECK (((kind)::text = ANY ((ARRAY['saml_config'::character varying, 'idp_create'::character varying, 'idp_update'::character varying])::text[]))),
    CONSTRAINT chk_sso_pending_changes_status CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'approved'::character varying, 'rejected'::character varying, 'expired'::character varying, 'superseded'::character varying])::text[])))
);


--
-- Name: TABLE sso_pending_changes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sso_pending_changes IS 'SSO configuration changes submitted by a platform administrator, awaiting approval by an owner of the organization';


--
-- Name: COLUMN sso_pending_changes.secret_encrypted; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sso_pending_changes.secret_encrypted IS 'Encrypted OIDC client secret for idp_create/idp_update; cleared once the change is decided';


--
-- Name: step_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.step_runs (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
