    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    error_message text,
    error_code character varying(100),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_step_runs_status CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'queued'::character varying, 'running'::character varying, 'completed'::character varying, 'partial'::character varying, 'failed'::character varying, 'skipped'::character varying, 'canceled'::character varying, 'timeout'::character varying])::text[])))
);


