-- Name: suppression_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.suppression_rules (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    tenant_id uuid NOT NULL,
    rule_id character varying(500),
    tool_name character varying(100),
    path_pattern character varying(1000),
    asset_id uuid,
    name character varying(255) NOT NULL,
    description text,
    suppression_type character varying(50) DEFAULT 'false_positive'::character varying NOT NULL,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    requested_by uuid,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    rejected_by uuid,
