    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_suppression_rules_at_least_one_criterion CHECK (((rule_id IS NOT NULL) OR (path_pattern IS NOT NULL) OR (asset_id IS NOT NULL))),
    CONSTRAINT chk_suppression_rules_status CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'approved'::character varying, 'rejected'::character varying, 'expired'::character varying])::text[]))),
    CONSTRAINT chk_suppression_rules_type CHECK (((suppression_type)::text = ANY ((ARRAY['false_positive'::character varying, 'accepted_risk'::character varying, 'wont_fix'::character varying])::text[])))
);


