--
-- Name: v_user_effective_role; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_user_effective_role AS
 SELECT m.user_id,
    m.tenant_id,
    (COALESCE(sr.slug,
        CASE
            WHEN ((m.role)::text = ANY ((ARRAY['member'::character varying, 'viewer'::character varying])::text[])) THEN m.role
            ELSE 'viewer'::character varying
        END))::character varying(50) AS role,
    sr.name AS role_name,
    sr.hierarchy_level,
    COALESCE(sr.has_full_data_access, false) AS has_full_data_access
   FROM (public.tenant_members m
     LEFT JOIN LATERAL ( SELECT (
                CASE r.id
                    WHEN '00000000-0000-0000-0000-000000000001'::uuid THEN 'owner'::text
                    WHEN '00000000-0000-0000-0000-000000000002'::uuid THEN 'admin'::text
                    WHEN '00000000-0000-0000-0000-000000000003'::uuid THEN 'member'::text
                    ELSE 'viewer'::text
                END)::character varying(50) AS slug,
            r.name,
            r.hierarchy_level,
            r.has_full_data_access
           FROM (public.user_roles ur
             JOIN public.roles r ON ((r.id = ur.role_id)))
          WHERE ((ur.user_id = m.user_id) AND (ur.tenant_id = m.tenant_id) AND (r.id = ANY (ARRAY['00000000-0000-0000-0000-000000000001'::uuid, '00000000-0000-0000-0000-000000000002'::uuid, '00000000-0000-0000-0000-000000000003'::uuid, '00000000-0000-0000-0000-000000000004'::uuid])))
          ORDER BY
                CASE r.id
                    WHEN '00000000-0000-0000-0000-000000000001'::uuid THEN 4
                    WHEN '00000000-0000-0000-0000-000000000002'::uuid THEN 3
                    WHEN '00000000-0000-0000-0000-000000000003'::uuid THEN 2
                    ELSE 1
                END DESC
         LIMIT 1) sr ON (true));


--
-- Name: VIEW v_user_effective_role; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_user_effective_role IS 'Team role per membership: the highest SYSTEM role held (by role id), else the membership label capped at member. Custom roles never count.';


