    detection_detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT chk_validation_evidence_detection_status CHECK (((detection_status)::text = ANY ((ARRAY['observed'::character varying, 'not_observed'::character varying, 'no_telemetry_source'::character varying, 'not_applicable'::character varying, 'not_evaluated'::character varying])::text[]))),
    CONSTRAINT chk_validation_evidence_outcome CHECK (((outcome)::text = ANY ((ARRAY['detected'::character varying, 'not_detected'::character varying, 'inconclusive'::character varying, 'error'::character varying, 'skipped'::character varying])::text[])))
);


