--
-- Name: vulnerabilities; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vulnerabilities (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    cve_id character varying(30),
    aliases text[] DEFAULT '{}'::text[],
    title character varying(500) NOT NULL,
    description text,
    severity character varying(20) DEFAULT 'unknown'::character varying NOT NULL,
    cvss_score numeric(3,1),
    cvss_vector character varying(200),
    epss_score numeric(8,6),
    epss_percentile numeric(9,6),
    cisa_kev_date_added timestamp with time zone,
    cisa_kev_due_date timestamp with time zone,
    cisa_kev_ransomware_use character varying(100),
    cisa_kev_notes text,
    exploit_available boolean DEFAULT false NOT NULL,
    exploit_maturity character varying(20) DEFAULT 'none'::character varying NOT NULL,
    reference_urls jsonb DEFAULT '[]'::jsonb NOT NULL,
    affected_versions jsonb DEFAULT '[]'::jsonb NOT NULL,
    fixed_versions text[] DEFAULT '{}'::text[],
    remediation text,
    published_at timestamp with time zone,
    modified_at timestamp with time zone,
    status character varying(30) DEFAULT 'open'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tenant_id uuid,
    scope_tenant_id uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    kind character varying(30) DEFAULT 'vulnerability'::character varying NOT NULL,
    namespace character varying(100) DEFAULT 'CVE'::character varying NOT NULL,
    external_id character varying(512),
    lifecycle character varying(20) DEFAULT 'published'::character varying NOT NULL,
    merged_into uuid,
    merged_into_scope uuid,
    origin character varying(20) DEFAULT 'report'::character varying NOT NULL,
    cvss_version character varying(10),
    nicknames text[] DEFAULT '{}'::text[] NOT NULL,
    CONSTRAINT chk_vuln_cve_compat CHECK (((((namespace)::text = 'CVE'::text) = (cve_id IS NOT NULL)) AND ((cve_id IS NULL) OR ((tenant_id IS NULL) AND ((external_id)::text = (cve_id)::text))))),
    CONSTRAINT chk_vuln_exploit_maturity CHECK (((exploit_maturity)::text = ANY ((ARRAY['none'::character varying, 'poc'::character varying, 'functional'::character varying, 'weaponized'::character varying, 'unknown'::character varying])::text[]))),
    CONSTRAINT chk_vuln_external_id CHECK (((external_id IS NOT NULL) AND ((external_id)::text <> ''::text))),
    CONSTRAINT chk_vuln_kind CHECK (((kind)::text = ANY ((ARRAY['vulnerability'::character varying, 'weakness'::character varying, 'misconfiguration'::character varying, 'exposure'::character varying, 'secret'::character varying, 'compliance'::character varying, 'malicious'::character varying])::text[]))),
    CONSTRAINT chk_vuln_lifecycle CHECK (((lifecycle)::text = ANY ((ARRAY['published'::character varying, 'reserved'::character varying, 'rejected'::character varying, 'withdrawn'::character varying, 'disputed'::character varying, 'deprecated'::character varying, 'merged'::character varying])::text[]))),
    CONSTRAINT chk_vuln_merged CHECK (((((lifecycle)::text = 'merged'::text) = (merged_into IS NOT NULL)) AND ((merged_into IS NULL) = (merged_into_scope IS NULL)) AND ((merged_into IS NULL) OR (merged_into <> id)) AND ((merged_into_scope IS NULL) OR ((merged_into_scope = '00000000-0000-0000-0000-000000000000'::uuid) OR (merged_into_scope = scope_tenant_id))))),
    CONSTRAINT chk_vuln_namespace CHECK (((namespace)::text ~ '^[A-Z][A-Z0-9_]{0,31}(:[A-Za-z0-9][A-Za-z0-9_.-]{0,63})?$'::text)),
    CONSTRAINT chk_vuln_origin CHECK (((origin)::text = ANY ((ARRAY['cve_list'::character varying, 'nvd'::character varying, 'osv'::character varying, 'ghsa'::character varying, 'kev'::character varying, 'rule_catalog'::character varying, 'report'::character varying, 'tenant'::character varying])::text[]))),
    CONSTRAINT chk_vuln_origin_scope CHECK ((((tenant_id IS NULL) AND ((origin)::text <> 'tenant'::text)) OR ((tenant_id IS NOT NULL) AND ((origin)::text = ANY ((ARRAY['report'::character varying, 'tenant'::character varying])::text[]))))),
    CONSTRAINT chk_vuln_scope_tenant CHECK ((scope_tenant_id = COALESCE(tenant_id, '00000000-0000-0000-0000-000000000000'::uuid))),
    CONSTRAINT chk_vuln_severity CHECK (((severity)::text = ANY ((ARRAY['critical'::character varying, 'high'::character varying, 'medium'::character varying, 'low'::character varying, 'info'::character varying, 'none'::character varying, 'unknown'::character varying])::text[]))),
    CONSTRAINT chk_vuln_status CHECK (((status)::text = ANY ((ARRAY['open'::character varying, 'patched'::character varying, 'mitigated'::character varying, 'not_affected'::character varying, 'investigating'::character varying])::text[])))
);


