INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc040001-0000-0000-0000-000000000005', 'cf000001-0000-0000-0000-000000000004', 'Req 5', 'Protect All Systems and Networks from Malicious Software', 'Malicious software is prevented, detected, and addressed.', 'Malware Protection', NULL, 5, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc040001-0000-0000-0000-000000000006', 'cf000001-0000-0000-0000-000000000004', 'Req 6', 'Develop and Maintain Secure Systems and Software', 'Bespoke and custom software are developed securely.', 'Secure Development', NULL, 6, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc040001-0000-0000-0000-000000000007', 'cf000001-0000-0000-0000-000000000004', 'Req 7', 'Restrict Access to System Components and Cardholder Data', 'Access to system components and cardholder data is limited to only those individuals whose jobs require such access.', 'Access Control', NULL, 7, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc040001-0000-0000-0000-000000000008', 'cf000001-0000-0000-0000-000000000004', 'Req 8', 'Identify Users and Authenticate Access', 'Systems and processes are used to identify users and authenticate access.', 'Authentication', NULL, 8, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc040001-0000-0000-0000-000000000009', 'cf000001-0000-0000-0000-000000000004', 'Req 9', 'Restrict Physical Access to Cardholder Data', 'Physical access to cardholder data and systems is restricted.', 'Physical Security', NULL, 9, '{}', '2026-10-06 03:16:51.965361+00');
