INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc040001-0000-0000-0000-000000000011', 'cf000001-0000-0000-0000-000000000004', 'Req 11', 'Test Security of Systems and Networks Regularly', 'Security of systems and networks is tested regularly.', 'Testing', NULL, 11, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc040001-0000-0000-0000-000000000012', 'cf000001-0000-0000-0000-000000000004', 'Req 12', 'Support Information Security with Policies and Programs', 'An information security policy is maintained.', 'Governance', NULL, 12, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc050001-0000-0000-0000-000000000001', 'cf000001-0000-0000-0000-000000000005', 'GV', 'Govern', 'The organizations cybersecurity risk management strategy, expectations, and policy are established, communicated, and monitored.', 'Governance', NULL, 1, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc050001-0000-0000-0000-000000000002', 'cf000001-0000-0000-0000-000000000005', 'ID', 'Identify', 'The organizations current cybersecurity risks are understood.', 'Identification', NULL, 2, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc050001-0000-0000-0000-000000000003', 'cf000001-0000-0000-0000-000000000005', 'PR', 'Protect', 'Safeguards to manage the organizations cybersecurity risks are used.', 'Protection', NULL, 3, '{}', '2026-10-06 03:16:51.965361+00');
