INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc050001-0000-0000-0000-000000000005', 'cf000001-0000-0000-0000-000000000005', 'RS', 'Respond', 'Actions regarding a detected cybersecurity incident are taken.', 'Response', NULL, 5, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc050001-0000-0000-0000-000000000006', 'cf000001-0000-0000-0000-000000000005', 'RC', 'Recover', 'Assets and operations affected by a cybersecurity incident are restored.', 'Recovery', NULL, 6, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc060001-0000-0000-0000-000000000001', 'cf000001-0000-0000-0000-000000000006', '164.308(a)(1)', 'Security Management Process', 'Implement policies and procedures to prevent, detect, contain, and correct security violations.', 'Administrative', NULL, 1, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc060001-0000-0000-0000-000000000002', 'cf000001-0000-0000-0000-000000000006', '164.308(a)(3)', 'Workforce Security', 'Implement policies and procedures to ensure members of the workforce have appropriate access.', 'Administrative', NULL, 2, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc060001-0000-0000-0000-000000000003', 'cf000001-0000-0000-0000-000000000006', '164.308(a)(4)', 'Information Access Management', 'Implement policies and procedures for authorizing access to ePHI.', 'Administrative', NULL, 3, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc060001-0000-0000-0000-000000000004', 'cf000001-0000-0000-0000-000000000006', '164.308(a)(5)', 'Security Awareness and Training', 'Implement a security awareness and training program for all members of the workforce.', 'Administrative', NULL, 4, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc060001-0000-0000-0000-000000000005', 'cf000001-0000-0000-0000-000000000006', '164.308(a)(6)', 'Security Incident Procedures', 'Implement policies and procedures to address security incidents.', 'Administrative', NULL, 5, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc060001-0000-0000-0000-000000000006', 'cf000001-0000-0000-0000-000000000006', '164.310(a)(1)', 'Facility Access Controls', 'Implement policies and procedures to limit physical access.', 'Physical', NULL, 6, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc060001-0000-0000-0000-000000000007', 'cf000001-0000-0000-0000-000000000006', '164.312(a)(1)', 'Access Control', 'Implement technical policies and procedures for computing systems that maintain ePHI.', 'Technical', NULL, 7, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc060001-0000-0000-0000-000000000008', 'cf000001-0000-0000-0000-000000000006', '164.312(b)', 'Audit Controls', 'Implement mechanisms to record and examine activity in systems containing ePHI.', 'Technical', NULL, 8, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc060001-0000-0000-0000-000000000009', 'cf000001-0000-0000-0000-000000000006', '164.312(c)(1)', 'Integrity', 'Implement policies and procedures to protect ePHI from improper alteration or destruction.', 'Technical', NULL, 9, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc060001-0000-0000-0000-000000000010', 'cf000001-0000-0000-0000-000000000006', '164.312(e)(1)', 'Transmission Security', 'Implement technical security measures to guard against unauthorized access to ePHI during transmission.', 'Technical', NULL, 10, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc070001-0000-0000-0000-000000000001', 'cf000001-0000-0000-0000-000000000007', 'Art. 5', 'Principles Relating to Processing', 'Personal data shall be processed lawfully, fairly, and in a transparent manner.', 'Data Processing', NULL, 1, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc070001-0000-0000-0000-000000000002', 'cf000001-0000-0000-0000-000000000007', 'Art. 6', 'Lawfulness of Processing', 'Processing shall be lawful only if the data subject has given consent.', 'Data Processing', NULL, 2, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc070001-0000-0000-0000-000000000003', 'cf000001-0000-0000-0000-000000000007', 'Art. 17', 'Right to Erasure', 'The data subject shall have the right to obtain erasure of personal data.', 'Data Subject Rights', NULL, 3, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc070001-0000-0000-0000-000000000004', 'cf000001-0000-0000-0000-000000000007', 'Art. 25', 'Data Protection by Design and Default', 'The controller shall implement appropriate technical and organisational measures.', 'Data Protection', NULL, 4, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc070001-0000-0000-0000-000000000005', 'cf000001-0000-0000-0000-000000000007', 'Art. 30', 'Records of Processing Activities', 'Each controller shall maintain a record of processing activities.', 'Accountability', NULL, 5, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc070001-0000-0000-0000-000000000006', 'cf000001-0000-0000-0000-000000000007', 'Art. 32', 'Security of Processing', 'The controller and processor shall implement appropriate technical and organisational security measures.', 'Security', NULL, 6, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc070001-0000-0000-0000-000000000007', 'cf000001-0000-0000-0000-000000000007', 'Art. 33', 'Notification of Breach to Authority', 'In case of a personal data breach, the controller shall notify the supervisory authority within 72 hours.', 'Breach Notification', NULL, 7, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc070001-0000-0000-0000-000000000008', 'cf000001-0000-0000-0000-000000000007', 'Art. 34', 'Communication of Breach to Data Subject', 'When the breach is likely to result in a high risk, the controller shall communicate the breach.', 'Breach Notification', NULL, 8, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc070001-0000-0000-0000-000000000009', 'cf000001-0000-0000-0000-000000000007', 'Art. 35', 'Data Protection Impact Assessment', 'Where processing is likely to result in a high risk, the controller shall carry out an assessment.', 'Risk Assessment', NULL, 9, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc070001-0000-0000-0000-000000000010', 'cf000001-0000-0000-0000-000000000007', 'Art. 37', 'Designation of Data Protection Officer', 'The controller and processor shall designate a data protection officer.', 'Governance', NULL, 10, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc080001-0000-0000-0000-000000000001', 'cf000001-0000-0000-0000-000000000008', 'CIS 1', 'Inventory and Control of Enterprise Assets', 'Actively manage all enterprise assets connected to the infrastructure.', 'Asset Management', NULL, 1, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc080001-0000-0000-0000-000000000002', 'cf000001-0000-0000-0000-000000000008', 'CIS 2', 'Inventory and Control of Software Assets', 'Actively manage all software on the network.', 'Software Management', NULL, 2, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc080001-0000-0000-0000-000000000003', 'cf000001-0000-0000-0000-000000000008', 'CIS 3', 'Data Protection', 'Develop processes and technical controls to identify and protect data.', 'Data Protection', NULL, 3, '{}', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc080001-0000-0000-0000-000000000004', 'cf000001-0000-0000-0000-000000000008', 'CIS 4', 'Secure Configuration of Enterprise Assets and Software', 'Establish and maintain secure configuration.', 'Configuration', NULL, 4, '{}', '2026-10-06 03:16:51.965361+00');
