INSERT INTO public.compliance_controls (id, framework_id, control_id, title, description, category, parent_control_id, sort_order, metadata, created_at) VALUES ('cc080001-0000-0000-0000-000000000009', 'cf000001-0000-0000-0000-000000000008', 'CIS 9', 'Email and Web Browser Protections', 'Improve protections and detections of email and web threats.', 'Endpoint Protection', NULL, 9, '{}', '2026-10-06 03:16:51.965361+00');
