INSERT INTO public.compliance_frameworks (id, tenant_id, name, slug, version, description, category, total_controls, is_system, is_active, metadata, created_at, updated_at) VALUES ('cf000001-0000-0000-0000-000000000001', NULL, 'OWASP Top 10', 'owasp', '2021', 'The OWASP Top 10 is a standard awareness document for developers and web application security representing a broad consensus about the most critical security risks to web applications.', 'industry', 10, true, true, '{}', '2026-10-06 03:16:51.965361+00', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_frameworks (id, tenant_id, name, slug, version, description, category, total_controls, is_system, is_active, metadata, created_at, updated_at) VALUES ('cf000001-0000-0000-0000-000000000002', NULL, 'SOC 2 Type II', 'soc2', '2017', 'SOC 2 is an auditing procedure that ensures service providers securely manage data to protect the interests of the organization and the privacy of its clients.', 'industry', 17, true, true, '{}', '2026-10-06 03:16:51.965361+00', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_frameworks (id, tenant_id, name, slug, version, description, category, total_controls, is_system, is_active, metadata, created_at, updated_at) VALUES ('cf000001-0000-0000-0000-000000000003', NULL, 'ISO 27001', 'iso_27001', '2022', 'ISO/IEC 27001 is an international standard for managing information security. It specifies requirements for establishing, implementing, maintaining, and continually improving an information security management system (ISMS).', 'regulatory', 20, true, true, '{}', '2026-10-06 03:16:51.965361+00', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_frameworks (id, tenant_id, name, slug, version, description, category, total_controls, is_system, is_active, metadata, created_at, updated_at) VALUES ('cf000001-0000-0000-0000-000000000004', NULL, 'PCI DSS', 'pci_dss', '4.0', 'The Payment Card Industry Data Security Standard (PCI DSS) is a set of security standards designed to ensure that all companies that accept, process, store or transmit credit card information maintain a secure environment.', 'regulatory', 12, true, true, '{}', '2026-10-06 03:16:51.965361+00', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_frameworks (id, tenant_id, name, slug, version, description, category, total_controls, is_system, is_active, metadata, created_at, updated_at) VALUES ('cf000001-0000-0000-0000-000000000005', NULL, 'NIST CSF', 'nist', '2.0', 'The NIST Cybersecurity Framework provides a policy framework of computer security guidance for how organizations can assess and improve their ability to prevent, detect, and respond to cyber attacks.', 'best_practice', 6, true, true, '{}', '2026-10-06 03:16:51.965361+00', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_frameworks (id, tenant_id, name, slug, version, description, category, total_controls, is_system, is_active, metadata, created_at, updated_at) VALUES ('cf000001-0000-0000-0000-000000000006', NULL, 'HIPAA', 'hipaa', '2013', 'The Health Insurance Portability and Accountability Act sets national standards for protecting sensitive patient health information from being disclosed without the patients consent or knowledge.', 'regulatory', 10, true, true, '{}', '2026-10-06 03:16:51.965361+00', '2026-10-06 03:16:51.965361+00');
INSERT INTO public.compliance_frameworks (id, tenant_id, name, slug, version, description, category, total_controls, is_system, is_active, metadata, created_at, updated_at) VALUES ('cf000001-0000-0000-0000-000000000007', NULL, 'GDPR', 'gdpr', '2016', 'The General Data Protection Regulation is a regulation in EU law on data protection and privacy for all individuals within the European Union and the European Economic Area.', 'regulatory', 10, true, true, '{}', '2026-10-06 03:16:51.965361+00', '2026-10-06 03:16:51.965361+00');
