INSERT INTO public.permissions (id, module_id, name, description, is_active, created_at) VALUES ('sensors:approve', 'sensors', 'Approve Sensors', 'Approve a pairing request: bind a sensor key to this organization (with re-authentication)', true, '2026-10-06 03:16:53.269588+00');
INSERT INTO public.permissions (id, module_id, name, description, is_active, created_at) VALUES ('sensors:grant:narrow', 'sensors', 'Narrow Sensor Grants', 'Narrow what a sensor may do (zones, tools, tier, targets, credentials, push ingest) and demote its trust level', true, '2026-10-06 03:16:53.269588+00');
INSERT INTO public.permissions (id, module_id, name, description, is_active, created_at) VALUES ('sensors:grant:widen', 'sensors', 'Widen Sensor Grants', 'Widen what a sensor may do and promote its trust level (audited, all administrators notified)', true, '2026-10-06 03:16:53.269588+00');
INSERT INTO public.permissions (id, module_id, name, description, is_active, created_at) VALUES ('sensors:revoke', 'sensors', 'Revoke Sensors', 'Revoke a sensor or one of its keys', true, '2026-10-06 03:16:53.269588+00');
INSERT INTO public.permissions (id, module_id, name, description, is_active, created_at) VALUES ('scans:freeze:override', 'scans', 'Override Scan Freeze Windows', 'Start a scan by hand while a freeze window is active (audited)', true, '2026-10-06 03:16:53.276573+00');


