INSERT INTO public.scan_profiles (id, tenant_id, name, description, is_default, is_system, tools_config, intensity, max_concurrent_scans, timeout_seconds, quality_gate, tags, metadata, created_by, created_at, updated_at) VALUES ('00000000-0000-0000-0001-000000000001', '00000000-0000-0000-0000-000000000000', 'Quick Discovery', 'Fast reconnaissance to discover subdomains and active hosts. Ideal for initial asset mapping.', false, true, '{"httpx": {"enabled": true, "timeout": 300, "severity": "info", "template_mode": "default"}, "subfinder": {"enabled": true, "timeout": 300, "severity": "info", "template_mode": "default"}}', 'low', 5, 1800, '{"enabled": false}', '{recon,discovery,quick}', '{"use_case": "initial_mapping", "typical_duration": "5-15 minutes"}', NULL, '2026-10-06 03:16:51.774021+00', '2026-10-06 03:16:51.774021+00');
INSERT INTO public.scan_profiles (id, tenant_id, name, description, is_default, is_system, tools_config, intensity, max_concurrent_scans, timeout_seconds, quality_gate, tags, metadata, created_by, created_at, updated_at) VALUES ('00000000-0000-0000-0001-000000000002', '00000000-0000-0000-0000-000000000000', 'Full SAST', 'Comprehensive static application security testing. Analyzes source code for vulnerabilities.', false, true, '{"semgrep": {"enabled": true, "timeout": 600, "severity": "medium", "template_mode": "default"}}', 'high', 3, 3600, '{"enabled": true, "max_high": 5, "max_total": -1, "max_medium": -1, "fail_on_high": false, "max_critical": 0, "fail_on_critical": true}', '{sast,code-analysis,security}', '{"use_case": "code_review", "typical_duration": "15-45 minutes"}', NULL, '2026-10-06 03:16:51.774021+00', '2026-10-06 03:16:51.774021+00');
INSERT INTO public.scan_profiles (id, tenant_id, name, description, is_default, is_system, tools_config, intensity, max_concurrent_scans, timeout_seconds, quality_gate, tags, metadata, created_by, created_at, updated_at) VALUES ('00000000-0000-0000-0001-000000000004', '00000000-0000-0000-0000-000000000000', 'Container Security', 'Scan container images for vulnerabilities, misconfigurations, and compliance issues.', false, true, '{"trivy": {"enabled": true, "timeout": 600, "severity": "medium", "template_mode": "default"}}', 'medium', 3, 2400, '{"enabled": true, "max_high": -1, "max_total": -1, "max_medium": -1, "fail_on_high": false, "max_critical": 0, "fail_on_critical": true}', '{container,docker,vulnerability,security}', '{"use_case": "container_scanning", "typical_duration": "10-30 minutes"}', NULL, '2026-10-06 03:16:51.774021+00', '2026-10-06 03:16:51.774021+00');
INSERT INTO public.scan_profiles (id, tenant_id, name, description, is_default, is_system, tools_config, intensity, max_concurrent_scans, timeout_seconds, quality_gate, tags, metadata, created_by, created_at, updated_at) VALUES ('00000000-0000-0000-0001-000000000005', '00000000-0000-0000-0000-000000000000', 'Web Vulnerability', 'Dynamic application security testing for web applications. Identifies vulnerabilities in running applications.', false, true, '{"nuclei": {"enabled": true, "timeout": 1800, "severity": "medium", "template_mode": "default"}}', 'medium', 2, 7200, '{"enabled": true, "max_high": 10, "max_total": -1, "max_medium": -1, "fail_on_high": false, "max_critical": 0, "fail_on_critical": true}', '{dast,web,vulnerability,security}', '{"use_case": "web_scanning", "typical_duration": "30-120 minutes"}', NULL, '2026-10-06 03:16:51.774021+00', '2026-10-06 03:16:51.774021+00');
INSERT INTO public.scan_profiles (id, tenant_id, name, description, is_default, is_system, tools_config, intensity, max_concurrent_scans, timeout_seconds, quality_gate, tags, metadata, created_by, created_at, updated_at) VALUES ('00000000-0000-0000-0001-000000000003', '00000000-0000-0000-0000-000000000000', 'Secret Detection', 'Detect hardcoded secrets, API keys, passwords, and tokens in code repositories.', false, true, '{"trufflehog": {"enabled": true, "timeout": 300, "severity": "high", "template_mode": "default"}, "betterleaks": {"enabled": true, "timeout": 300, "severity": "high", "template_mode": "default"}}', 'medium', 5, 1800, '{"enabled": true, "max_high": -1, "max_total": -1, "max_medium": -1, "fail_on_high": false, "max_critical": 0, "fail_on_critical": true}', '{secrets,credentials,security}', '{"use_case": "secret_scanning", "typical_duration": "5-20 minutes"}', NULL, '2026-10-06 03:16:51.774021+00', '2026-10-06 03:16:52.598896+00');
INSERT INTO public.scan_profiles (id, tenant_id, name, description, is_default, is_system, tools_config, intensity, max_concurrent_scans, timeout_seconds, quality_gate, tags, metadata, created_by, created_at, updated_at) VALUES ('00000000-0000-0000-0001-000000000006', '00000000-0000-0000-0000-000000000000', 'CI/CD Strict', 'Strict security scanning for CI/CD pipelines. Combines SAST, secrets, and container scanning with strict quality gates.', false, true, '{"trivy": {"enabled": true, "timeout": 300, "severity": "high", "template_mode": "default"}, "semgrep": {"enabled": true, "timeout": 300, "severity": "high", "template_mode": "default"}, "betterleaks": {"enabled": true, "timeout": 180, "severity": "high", "template_mode": "default"}}', 'high', 3, 1800, '{"enabled": true, "max_high": 0, "max_total": -1, "max_medium": 5, "fail_on_high": true, "max_critical": 0, "fail_on_critical": true}', '{ci-cd,pipeline,strict,security}', '{"use_case": "ci_cd_integration", "typical_duration": "10-30 minutes"}', NULL, '2026-10-06 03:16:51.774021+00', '2026-10-06 03:16:52.598896+00');
INSERT INTO public.scan_profiles (id, tenant_id, name, description, is_default, is_system, tools_config, intensity, max_concurrent_scans, timeout_seconds, quality_gate, tags, metadata, created_by, created_at, updated_at) VALUES ('00000000-0000-0000-0001-000000000007', '00000000-0000-0000-0000-000000000000', 'Compliance Scan', 'Comprehensive security scan for compliance requirements. Uses all available tools with zero-tolerance quality gates.', false, true, '{"trivy": {"enabled": true, "timeout": 600, "severity": "info", "template_mode": "default"}, "nuclei": {"enabled": true, "timeout": 1800, "severity": "info", "template_mode": "default"}, "semgrep": {"enabled": true, "timeout": 600, "severity": "info", "template_mode": "default"}, "trufflehog": {"enabled": true, "timeout": 300, "severity": "info", "template_mode": "default"}, "betterleaks": {"enabled": true, "timeout": 300, "severity": "info", "template_mode": "default"}}', 'high', 2, 14400, '{"enabled": true, "max_high": 0, "max_total": 0, "max_medium": 0, "fail_on_high": true, "max_critical": 0, "fail_on_critical": true}', '{compliance,audit,security,comprehensive}', '{"use_case": "compliance_audit", "typical_duration": "60-240 minutes"}', NULL, '2026-10-06 03:16:51.774021+00', '2026-10-06 03:16:52.598896+00');


