    ADD CONSTRAINT chk_findings_source_interop CHECK ((((native_vuln_id IS NULL) OR (length(native_vuln_id) <= 256)) AND ((native_scheme IS NULL) OR (length(native_scheme) <= 64)) AND ((source_meta IS NULL) OR ((jsonb_typeof(source_meta) = 'object'::text) AND (octet_length((source_meta)::text) <= 16384))) AND ((scores IS NULL) OR ((jsonb_typeof(scores) = 'array'::text) AND (jsonb_array_length(scores) <= 32))) AND ((vulnerability_ids IS NULL) OR ((jsonb_typeof(vulnerability_ids) = 'array'::text) AND (jsonb_array_length(vulnerability_ids) <= 64))) AND ((source_extra IS NULL) OR ((jsonb_typeof(source_extra) = 'object'::text) AND (octet_length((source_extra)::text) <= 49152))) AND ((location_key IS NULL) OR (length(location_key) <= 512)) AND ((vex_status IS NULL) OR (vex_status = ANY (ARRAY['not_affected'::text, 'affected'::text, 'fixed'::text, 'under_investigation'::text]))) AND ((vex_justification IS NULL) OR (vex_justification = ANY (ARRAY['component_not_present'::text, 'vulnerable_code_not_present'::text, 'vulnerable_code_not_in_execute_path'::text, 'vulnerable_code_cannot_be_controlled_by_adversary'::text, 'inline_mitigations_already_exist'::text]))) AND ((vex_statement IS NULL) OR (length(vex_statement) <= 4096)) AND ((vex_source IS NULL) OR (length(vex_source) <= 512)))) NOT VALID;


